/* AUTOGENERATED by scripts/build_bundle.py — do not edit by hand */
/* Bundles: player-utils.js, player-sound.js, player-lobby.js, player-reveal.js, player-end.js, player-lightning.js, player-game.js, player-core.js */

/* ============ player-utils.js ============ */

/**
 * Quizify Player - Utility Module
 * Shared state, view management, DOM helpers, connection indicator, QR, toast, collapsibles
 */

(function () {
    'use strict';

    var utils = window.QuizifyUtils || {};

    // ============================================
    // Shared Mutable State (used by all player modules)
    // ============================================

    var state = {
        ws: null,
        playerName: null,
        playerId: null,
        sessionToken: null,
        isAdmin: false,
        currentView: null,
        currentPhase: 'LOBBY',
        reconnectAttempts: 0,
        isReconnecting: false,
        intentionalLeave: false,
        playerColor: '',  // assigned by server on join
    };

    // ============================================
    // Constants
    // ============================================

    var MAX_RECONNECT_ATTEMPTS = 10;
    var MAX_RECONNECT_DELAY_MS = 30000;
    // Name limit lives in utils.js (QuizifyUtils.MAX_NAME_LENGTH) so the
    // player flow and the admin modal share one rule. Mirror it locally
    // for any legacy reference; validateName() delegates to the shared one.
    var MAX_NAME_LENGTH = (window.QuizifyUtils && window.QuizifyUtils.MAX_NAME_LENGTH) || 20;
    var SESSION_STORAGE_TOKEN = 'quizify_session_token';
    var SESSION_STORAGE_NAME = 'quizify_player_name';

    // ============================================
    // HTML Escaping
    // ============================================

    function escapeHtml(text) {
        return utils.escapeHtml(text);
    }

    // ============================================
    // View Management
    // ============================================

    var viewIds = [
        'loading-view', 'not-found-view', 'ended-view', 'in-progress-view',
        'join-view', 'lobby-view', 'game-view', 'reveal-view',
        'paused-view', 'end-view', 'connection-lost-view'
    ];

    function showView(viewId) {
        var revealedEl = null;
        for (var i = 0; i < viewIds.length; i++) {
            var el = document.getElementById(viewIds[i]);
            if (el) {
                if (viewIds[i] === viewId) {
                    el.classList.remove('hidden');
                    el.classList.add('active');
                    revealedEl = el;
                } else {
                    el.classList.add('hidden');
                    el.classList.remove('active');
                }
            }
        }
        state.currentView = viewId;

        // Round indicator next to the wordmark — only visible on the
        // reveal view. Text itself is populated by renderFinaleReveal.
        var headerRound = document.getElementById('player-header-round');
        if (headerRound) {
            if (viewId === 'reveal-view') headerRound.removeAttribute('hidden');
            else headerRound.setAttribute('hidden', '');
        }

        // Re-run i18n on the view we just revealed. The page-wide
        // initPageTranslations runs once on load, but buttons inside views
        // that start hidden (#next-round-btn in #reveal-view, etc.) skip
        // translation if our translator looks at offsetParent — and even
        // when it doesn't, swapping languages later won't reach them until
        // we re-translate. Cheap to do per view-show.
        if (revealedEl && window.QuizifyI18n && window.QuizifyI18n.isReady()) {
            window.QuizifyI18n.initPageTranslations(revealedEl);
        }

        // Auto-focus name input on join view
        if (viewId === 'join-view') {
            setTimeout(function () {
                var nameInput = document.getElementById('name-input');
                if (nameInput) nameInput.focus();
            }, 100);
        }
    }

    // ============================================
    // Formatting
    // ============================================

    function formatPoints(n) {
        return utils.formatPoints(n);
    }

    function formatTime(seconds) {
        return utils.formatTime(seconds);
    }

    // ============================================
    // WebSocket Factory
    // ============================================

    function createWebSocket(path, handlers) {
        var proto = location.protocol === 'https:' ? 'wss:' : 'ws:';
        var url = proto + '//' + location.host + path;

        var ws = new WebSocket(url);

        ws.onopen = function () {
            state.reconnectAttempts = 0;
            state.isReconnecting = false;
            hideReconnectingOverlay();
            updateConnectionIndicator('connected');
            if (handlers.onOpen) handlers.onOpen(ws);
        };

        ws.onmessage = function (evt) {
            try {
                var msg = JSON.parse(evt.data);
                if (handlers.onMessage) handlers.onMessage(msg);
            } catch (e) {
                console.error('[Quizify] Bad message:', e);
            }
        };

        ws.onclose = function () {
            if (state.intentionalLeave) {
                state.intentionalLeave = false;
                return;
            }
            if (state.playerName && state.reconnectAttempts < MAX_RECONNECT_ATTEMPTS) {
                state.isReconnecting = true;
                state.reconnectAttempts++;
                showReconnectingOverlay();
                updateConnectionIndicator('reconnecting');
                var delay = getReconnectDelay();
                console.log('[Quizify] WS closed. Reconnecting in ' + delay + 'ms (attempt ' + state.reconnectAttempts + ')');
                setTimeout(function () {
                    if (handlers.onReconnect) handlers.onReconnect();
                }, delay);
            } else if (state.reconnectAttempts >= MAX_RECONNECT_ATTEMPTS) {
                state.isReconnecting = false;
                hideReconnectingOverlay();
                updateConnectionIndicator('disconnected');
                showView('connection-lost-view');
            }
            if (handlers.onClose) handlers.onClose();
        };

        ws.onerror = function () {
            if (ws) ws.close();
        };

        return ws;
    }

    function getReconnectDelay() {
        return Math.min(1000 * Math.pow(2, state.reconnectAttempts), MAX_RECONNECT_DELAY_MS);
    }

    // ============================================
    // Connection Indicator
    // ============================================

    function updateConnectionIndicator(status) {
        var el = document.getElementById('conn-status');
        if (!el) {
            el = document.createElement('div');
            el.id = 'conn-status';
            el.style.cssText = 'position:fixed;bottom:12px;right:12px;display:flex;align-items:center;gap:6px;font-size:0.75rem;color:#6E6A5C;z-index:100;';
            document.body.appendChild(el);
        }
        // Soft Parlor palette: connected = sage, warning = sun, error = warm brick.
        var colors = { connected: '#7FA897', reconnecting: '#E8C47F', disconnected: '#D66A6A' };
        var glow = { connected: 'rgba(127,168,151,0.45)', reconnecting: 'rgba(232,196,127,0.45)', disconnected: 'rgba(214,106,106,0.45)' };
        var color = colors[status] || '#6E6A5C';
        var glowColor = glow[status] || 'rgba(110,106,92,0.25)';
        // Dot only — no text label
        el.innerHTML = '<span style="width:10px;height:10px;border-radius:50%;display:inline-block;background:' +
            color + ';box-shadow:0 0 10px ' + glowColor + ';"></span>';
    }

    // ============================================
    // Reconnecting Overlay
    // ============================================

    function showReconnectingOverlay() {
        var overlay = document.getElementById('reconnecting-overlay');
        if (overlay) overlay.classList.remove('hidden');
    }

    function hideReconnectingOverlay() {
        var overlay = document.getElementById('reconnecting-overlay');
        if (overlay) overlay.classList.add('hidden');
    }

    // ============================================
    // Leaderboard Rendering
    // ============================================

    function renderLeaderboard(containerId, players, myName) {
        var container = typeof containerId === 'string'
            ? document.getElementById(containerId)
            : containerId;
        if (!container) return;

        container.innerHTML = players
            .map(function (p, i) {
                var rank = p.rank || i + 1;
                var rankClass = rank <= 3 ? ' rank-' + rank : '';
                var youBadge = (myName && p.name === myName)
                    ? '<span class="you-badge">(you)</span>' : '';
                return '<div class="leaderboard-row">' +
                    '<span class="leaderboard-rank' + rankClass + '">' + rank + '</span>' +
                    '<span class="leaderboard-name">' + escapeHtml(p.name) + youBadge + '</span>' +
                    '<span class="leaderboard-score">' + p.score + '</span>' +
                    (p.streak > 1 ? '<span class="leaderboard-streak">' + p.streak + 'x</span>' : '') +
                    '</div>';
            })
            .join('');
    }

    // ============================================
    // Player Cards Rendering
    // ============================================

    function renderPlayerCards(containerId, players) {
        var container = typeof containerId === 'string'
            ? document.getElementById(containerId)
            : containerId;
        if (!container) return;

        var list = Array.isArray(players) ? players : Object.values(players);

        container.innerHTML = list
            .map(function (p) {
                var name = typeof p === 'string' ? p : (p.name || p);
                var isYou = name === state.playerName;
                var isDisconnected = p.connected === false;
                var color = (p.color) || '';
                var classes = 'player-card' +
                    (isYou ? ' player-card--you' : '') +
                    (isDisconnected ? ' player-card--disconnected' : '');
                var colorStyle = color ? ' style="--player-color:' + color + ';border-left:4px solid ' + color + ';"' : '';
                var awayBadge = isDisconnected ? '<span class="away-badge">(away)</span>' : '';
                var youBadge = isYou ? '<span class="you-badge">(you)</span>' : '';
                return '<div class="' + classes + '"' + colorStyle + ' data-player="' + escapeHtml(name) + '">' +
                    '<span class="player-color-dot" style="background:' + (color || '#888') + '"></span>' +
                    '<span class="player-name">' + escapeHtml(name) + youBadge + awayBadge + '</span>' +
                    '</div>';
            })
            .join('');
    }

    // ============================================
    // Collapsibles
    // ============================================

    function setupCollapsibles() {
        var headers = document.querySelectorAll('.section-header-collapsible');
        for (var i = 0; i < headers.length; i++) {
            (function (header) {
                // Skip if already wired
                if (header.dataset.collapsibleInit) return;
                header.dataset.collapsibleInit = '1';

                header.addEventListener('click', function () {
                    var section = header.closest('.section-collapsible');
                    if (!section) return;

                    var isCollapsed = section.classList.contains('collapsed');
                    if (isCollapsed) {
                        section.classList.remove('collapsed');
                        header.setAttribute('aria-expanded', 'true');
                    } else {
                        section.classList.add('collapsed');
                        header.setAttribute('aria-expanded', 'false');
                    }
                });
            })(headers[i]);
        }
    }

    // Paint the static UI emoji-icon spans with the shared Rounded Duotone
    // SVG set (#225 P4). Any element carrying both `.qz-icon` and a
    // `data-ui-icon="<name>"` gets its emoji glyph swapped for the matching
    // window.QuizifyIcons.uiIcon() <svg>. The existing layout class
    // (.section-icon / .control-icon / .btn-icon / .paused-icon / etc.) and
    // the qz-icon--<tint> class stay put — we only replace innerHTML. Safe to
    // call more than once; already-painted spans just get re-filled.
    function paintUiIcons(root) {
        var Icons = window.QuizifyIcons;
        if (!Icons || !Icons.uiIcon) return;
        var scope = root || document;
        var slots = scope.querySelectorAll('.qz-icon[data-ui-icon]');
        for (var i = 0; i < slots.length; i++) {
            var name = slots[i].getAttribute('data-ui-icon');
            var svg = Icons.uiIcon(name);
            if (svg) slots[i].innerHTML = svg;
        }
    }

    // ============================================
    // QR Code Generation
    // ============================================

    function generateQR(containerId, url) {
        var container = typeof containerId === 'string'
            ? document.getElementById(containerId)
            : containerId;
        if (!container || !url) return;

        container.innerHTML = '';

        if (typeof QRCode !== 'undefined') {
            new QRCode(container, {
                text: url,
                width: 128,
                height: 128,
                colorDark: '#000000',
                colorLight: '#ffffff',
                correctLevel: QRCode.CorrectLevel.M
            });
        } else {
            container.innerHTML = '<p class="status-error">QR code library not loaded</p>';
        }
    }

    // ============================================
    // Toast Notification
    // ============================================

    function showToast(message, duration) {
        duration = duration || 3000;
        var toast = document.getElementById('error-toast');
        if (!toast) {
            toast = document.createElement('div');
            toast.id = 'error-toast';
            toast.style.cssText = 'position:fixed;top:16px;left:50%;transform:translateX(-50%);' +
                'background:#D65858;color:white;padding:10px 20px;border-radius:10px;' +
                'font-size:0.85rem;z-index:9999;opacity:0;transition:opacity 0.3s;pointer-events:none;';
            document.body.appendChild(toast);
        }
        toast.textContent = message;
        toast.style.opacity = '1';
        setTimeout(function () { toast.style.opacity = '0'; }, duration);
    }

    // ============================================
    // Session Storage Helpers
    // ============================================

    function saveSession(token, name) {
        try {
            sessionStorage.setItem(SESSION_STORAGE_TOKEN, token);
            sessionStorage.setItem(SESSION_STORAGE_NAME, name);
        } catch (e) { /* storage unavailable */ }
    }

    function getSession() {
        try {
            return {
                token: sessionStorage.getItem(SESSION_STORAGE_TOKEN),
                name: sessionStorage.getItem(SESSION_STORAGE_NAME)
            };
        } catch (e) {
            return { token: null, name: null };
        }
    }

    function clearSession() {
        try {
            sessionStorage.removeItem(SESSION_STORAGE_TOKEN);
            sessionStorage.removeItem(SESSION_STORAGE_NAME);
        } catch (e) { /* storage unavailable */ }
    }

    // ============================================
    // Name Validation
    // ============================================

    function validateName(name) {
        // Delegate to the shared, i18n-aware validator (utils.js). Kept as
        // a thin wrapper so player-core's pu.validateName() calls are
        // unchanged. Falls back to a local check only if utils.js somehow
        // didn't load (it's a hard dependency, loaded before this bundle).
        if (utils && utils.validateName) {
            return utils.validateName(name);
        }
        var trimmed = (name || '').trim();
        if (!trimmed) {
            return { valid: false, error: 'Please enter a name' };
        }
        if (trimmed.length > MAX_NAME_LENGTH) {
            return { valid: false, error: 'Name too long (max ' + MAX_NAME_LENGTH + ' characters)' };
        }
        return { valid: true, name: trimmed };
    }

    // ============================================
    // Score Animation
    // ============================================

    function easeOutQuart(t) {
        return 1 - Math.pow(1 - t, 4);
    }

    /**
     * Animate a numeric value in a DOM element from start to end
     */
    function animateValue(element, start, end, duration) {
        if (!element) return;
        if (start === end) { element.textContent = end; return; }
        var startTime = null;
        function step(timestamp) {
            if (!startTime) startTime = timestamp;
            var progress = Math.min((timestamp - startTime) / duration, 1);
            var value = Math.round(start + (end - start) * easeOutQuart(progress));
            element.textContent = value;
            if (progress < 1) requestAnimationFrame(step);
        }
        requestAnimationFrame(step);
    }

    /**
     * Show a floating +N pts popup above a target element
     */
    function showPointsPopup(targetElement, points, options) {
        if (!targetElement || !points) return;
        options = options || {};
        var popup = document.createElement('div');
        popup.className = 'points-popup' + (options.isStreak ? ' points-popup--streak' : '');
        popup.textContent = (points > 0 ? '+' : '') + points;
        document.body.appendChild(popup);

        var rect = targetElement.getBoundingClientRect();
        popup.style.cssText = [
            'position:fixed',
            'left:' + (rect.left + rect.width / 2) + 'px',
            'top:' + (rect.top - 10) + 'px',
            'transform:translateX(-50%)',
            'pointer-events:none',
            'z-index:9999',
        ].join(';');

        popup.addEventListener('animationend', function () {
            if (popup.parentNode) popup.parentNode.removeChild(popup);
        });
    }

    // ============================================
    // Export
    // ============================================

    window.QuizifyPlayerUtils = {
        state: state,
        escapeHtml: escapeHtml,
        showView: showView,
        formatPoints: formatPoints,
        formatTime: formatTime,
        createWebSocket: createWebSocket,
        updateConnectionIndicator: updateConnectionIndicator,
        renderLeaderboard: renderLeaderboard,
        renderPlayerCards: renderPlayerCards,
        setupCollapsibles: setupCollapsibles,
        paintUiIcons: paintUiIcons,
        generateQR: generateQR,
        showToast: showToast,
        saveSession: saveSession,
        getSession: getSession,
        clearSession: clearSession,
        validateName: validateName,
        MAX_RECONNECT_ATTEMPTS: MAX_RECONNECT_ATTEMPTS,
        animateValue: animateValue,
        showPointsPopup: showPointsPopup
    };

})();


/* ============ player-sound.js ============ */

/**
 * Quizify Player - Sound Module
 *
 * Short audio cues played on the player's own phone:
 *   - correct answer  → rising two-note chime
 *   - wrong answer     → low buzzer
 *   - last-5s ticking  → soft single tick per second
 *
 * All cues are synthesised with the Web Audio API (oscillators +
 * gain envelopes) so the integration ships no audio assets and the
 * page weight is unchanged.
 *
 * Mobile browsers require the AudioContext to be created/resumed from
 * a user gesture. We lazily create it and resume it on the first tap
 * anywhere (the player always taps to join / answer), so by the time a
 * cue fires the context is unlocked. If the user never interacts (or
 * the browser has no Web Audio support) every call is a silent no-op.
 *
 * A mute preference is persisted in localStorage and toggled via the
 * speaker button in the player header.
 */
(function () {
    'use strict';

    var MUTE_KEY = 'quizify_sound_muted';

    var ctx = null;          // lazily-created AudioContext
    var muted = false;       // user preference
    var _lastTickSecond = null;

    try {
        muted = window.localStorage.getItem(MUTE_KEY) === '1';
    } catch (e) {
        muted = false;
    }

    function supported() {
        return typeof (window.AudioContext || window.webkitAudioContext) === 'function';
    }

    function ensureCtx() {
        if (muted || !supported()) return null;
        if (!ctx) {
            var Ctor = window.AudioContext || window.webkitAudioContext;
            try {
                ctx = new Ctor();
            } catch (e) {
                ctx = null;
                return null;
            }
        }
        // Autoplay policy: context may start/become suspended; resume is
        // a no-op if already running and safe to call repeatedly.
        if (ctx.state === 'suspended' && typeof ctx.resume === 'function') {
            ctx.resume().catch(function () { /* ignore */ });
        }
        return ctx;
    }

    // Unlock audio on the first user gesture so later programmatic cues
    // are allowed to play on mobile.
    function unlock() {
        ensureCtx();
    }
    document.addEventListener('pointerdown', unlock, { once: false, passive: true });
    document.addEventListener('keydown', unlock, { once: false, passive: true });

    /**
     * Play a single tone with a short attack/decay envelope.
     * @param {number} freq   - frequency in Hz
     * @param {number} start  - delay before the tone starts (seconds)
     * @param {number} dur    - tone duration (seconds)
     * @param {string} type   - oscillator type
     * @param {number} peak   - peak gain (0..1)
     */
    function tone(freq, start, dur, type, peak) {
        var ac = ensureCtx();
        if (!ac) return;
        var t0 = ac.currentTime + start;
        var osc = ac.createOscillator();
        var gain = ac.createGain();
        osc.type = type || 'sine';
        osc.frequency.value = freq;
        // Click-free envelope.
        gain.gain.setValueAtTime(0.0001, t0);
        gain.gain.exponentialRampToValueAtTime(peak || 0.18, t0 + 0.012);
        gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
        osc.connect(gain);
        gain.connect(ac.destination);
        osc.start(t0);
        osc.stop(t0 + dur + 0.02);
    }

    /** Rising two-note "correct" chime. */
    function playCorrect() {
        if (muted) return;
        tone(660, 0, 0.14, 'sine', 0.18);   // E5
        tone(990, 0.11, 0.20, 'sine', 0.18); // B5
    }

    /** Low "wrong" buzzer. */
    function playWrong() {
        if (muted) return;
        tone(196, 0, 0.26, 'sawtooth', 0.12); // G3
        tone(146, 0.05, 0.26, 'sawtooth', 0.10); // D3
    }

    /** Soft tick for the time-running-out countdown (last 5 seconds). */
    function playTick() {
        if (muted) return;
        tone(880, 0, 0.05, 'square', 0.06);
    }

    /**
     * Drive the last-5s ticking from a remaining-seconds value. Plays at
     * most one tick per whole second and only inside the 1..5s window.
     * Reset must be called when a new question starts.
     * @param {number} remaining - seconds left
     */
    function tickFromRemaining(remaining) {
        if (muted) return;
        var sec = Math.ceil(remaining);
        if (sec <= 0 || sec > 5) return;
        if (sec === _lastTickSecond) return;
        _lastTickSecond = sec;
        playTick();
    }

    /** Clear the per-question tick guard so the next round can tick again. */
    function resetTick() {
        _lastTickSecond = null;
    }

    function isMuted() {
        return muted;
    }

    function setMuted(value) {
        muted = !!value;
        try {
            window.localStorage.setItem(MUTE_KEY, muted ? '1' : '0');
        } catch (e) { /* ignore */ }
        if (!muted) ensureCtx(); // warm up on un-mute (still a gesture)
        return muted;
    }

    function toggleMute() {
        return setMuted(!muted);
    }

    window.QuizifyPlayerSound = {
        playCorrect: playCorrect,
        playWrong: playWrong,
        playTick: playTick,
        tickFromRemaining: tickFromRemaining,
        resetTick: resetTick,
        isMuted: isMuted,
        setMuted: setMuted,
        toggleMute: toggleMute
    };
})();


/* ============ player-lobby.js ============ */

/**
 * Quizify Player - Lobby Module
 * Lobby rendering, player list, QR code, admin controls, "How to Play" section
 */

(function () {
    'use strict';

    var pu = window.QuizifyPlayerUtils;
    var state = pu.state;

    // ============================================
    // Player List Rendering
    // ============================================

    var previousPlayers = [];

    // Variant B+D layout. Paints the hero (mega avatar + name + "DU BIST DRIN")
    // for this player, and the orbit chips for the OTHER players. The
    // count line reads "+ N weitere" or "Du wartest noch allein…". Pure
    // DOM writes — no state of its own; relies on state.playerName as
    // the source of truth for "who am I".
    function _renderHeroAndOrbits(players, data) {
        var hero = document.getElementById('pl-mega-avatar');
        var nameEl = document.getElementById('pl-mega-name');
        var alsoEl = document.getElementById('pl-also');
        var orbits = document.getElementById('player-list');
        var metaEl = document.getElementById('pl-meta');
        if (!orbits) return;  // legacy markup — nothing to paint

        var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
        var myName = state.playerName || '';
        var me = null;
        var others = [];
        for (var i = 0; i < players.length; i++) {
            var p = players[i];
            if (p && p.name === myName) me = p;
            else others.push(p);
        }

        // Hero — only meaningful once we know our color from the server.
        if (hero && nameEl) {
            var initial = (myName || '?').charAt(0).toUpperCase();
            var color = (me && me.color) || state.playerColor || 'var(--color-accent-primary)';
            hero.textContent = initial;
            hero.style.background = color;
            hero.style.boxShadow = '0 0 0 6px ' + _hexWithAlpha(color, 0.22);
            nameEl.textContent = myName || '…';
        }

        // Meta line under the hero: difficulty + round count if known.
        if (metaEl) {
            var bits = [];
            var diffIcons = { 'easy': '🌱', 'medium': '🎯', 'hard': '🔥' };
            var diff = data && (data.difficulty || data.game_difficulty);
            if (diff && diffIcons[diff]) bits.push(diffIcons[diff] + ' ' + t('difficulties.' + diff));
            var total = data && (data.total_rounds || data.num_rounds);
            if (total) bits.push(total + ' ' + t('admin.summaryRoundsUnit'));
            metaEl.textContent = bits.length ? bits.join(' · ') : t('lobby.gameLobby');
        }

        // Companion line.
        if (alsoEl) {
            if (others.length === 0) {
                alsoEl.textContent = t('lobby.aloneWaiting');
            } else if (others.length === 1) {
                alsoEl.textContent = t('lobby.alsoOne');
            } else {
                alsoEl.textContent = t('lobby.alsoMany', { count: others.length });
            }
        }

        // Orbit chips — one per OTHER player. Uses the same color the
        // server assigned so chips match what each player sees on their
        // own phone.
        orbits.innerHTML = others.map(function (p) {
            var initial = (p.name || '?').charAt(0).toUpperCase();
            var bg = p.color || '#A89E89';
            var awayClass = p.connected === false ? ' is-away' : '';
            var hostClass = p.is_admin ? ' is-host' : '';
            var hostMark = p.is_admin ? '<span class="pl-orbit-host" aria-hidden="true">👑</span>' : '';
            return '<div class="pl-orbit' + awayClass + hostClass + '" data-player="' + _escape(p.name) + '">' +
                '<span class="pl-orbit-av" style="background:' + bg + '">' + _escape(initial) + '</span>' +
                '<span class="pl-orbit-nm">' + _escape(p.name || '') + '</span>' +
                hostMark +
            '</div>';
        }).join('');
    }

    // Tiny helpers — keep scope tight.
    function _escape(s) {
        return String(s == null ? '' : s)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
    }
    function _hexWithAlpha(hex, alpha) {
        // Accepts #RRGGBB or already-rgba/var() — fallback to original.
        if (typeof hex !== 'string' || !hex.startsWith('#') || hex.length !== 7) return hex;
        var r = parseInt(hex.slice(1, 3), 16);
        var g = parseInt(hex.slice(3, 5), 16);
        var b = parseInt(hex.slice(5, 7), 16);
        return 'rgba(' + r + ',' + g + ',' + b + ',' + alpha + ')';
    }

    /**
     * Render the full lobby view from game state
     * @param {Object} data - game_state message
     */
    function renderLobby(data) {
        var players = data.players || [];

        // Player count badge
        var countBadgeEl = document.getElementById('player-count-badge');
        if (countBadgeEl) countBadgeEl.textContent = players.length;

        // Difficulty badge — was rendering as an empty pill because no
        // code wrote into it. Map server difficulty value to a localised
        // label via i18n + a small icon.
        var diffBadgeEl = document.getElementById('lobby-difficulty-badge');
        if (diffBadgeEl) {
            var diffIcons = { 'easy': '🌱', 'medium': '🎯', 'hard': '🔥' };
            var diff = data.difficulty || data.game_difficulty || '';
            if (diff && diffIcons[diff]) {
                diffBadgeEl.textContent = diffIcons[diff] + ' ' + t('difficulties.' + diff);
                diffBadgeEl.classList.remove('hidden');
            } else {
                // No difficulty info yet — hide the empty pill instead of
                // rendering a hollow placeholder.
                diffBadgeEl.classList.add('hidden');
                diffBadgeEl.textContent = '';
            }
        }

        // Players summary count
        var playersSummaryEl = document.getElementById('players-summary');
        if (playersSummaryEl) playersSummaryEl.textContent = players.length;

        // Empty state
        var playersEmptyEl = document.getElementById('players-empty');
        if (playersEmptyEl) playersEmptyEl.classList.toggle('hidden', players.length > 0);

        // Variant B+D layout: paint the hero (mega avatar + name + tag),
        // then render OTHER players as orbit chips. Falls back gracefully
        // on legacy markup — if the hero nodes aren't present, the orbit
        // call still writes into #player-list as before.
        _renderHeroAndOrbits(players, data);

        // Detect newly joined players and add animation class
        var previousNames = previousPlayers.map(function (p) { return p.name; });
        var listEl = document.getElementById('player-list');
        if (listEl) {
            var cards = listEl.querySelectorAll('.player-card');
            for (var i = 0; i < cards.length; i++) {
                var name = cards[i].getAttribute('data-player');
                if (name && previousNames.indexOf(name) === -1) {
                    cards[i].classList.add('is-new');
                }
            }
            // Remove animation class after transition
            setTimeout(function () {
                var newCards = listEl.querySelectorAll('.is-new');
                for (var j = 0; j < newCards.length; j++) {
                    newCards[j].classList.remove('is-new');
                }
            }, 2000);
        }

        previousPlayers = players.slice();

        // Admin controls
        updateAdminControls(players);

        // QR code / invite section
        if (data.join_url) {
            setupInviteSection(data.join_url);
        }
    }

    // ============================================
    // Player Joined / Left Handlers
    // ============================================

    function handlePlayerJoined(data) {
        var players = data.players || [];

        var countBadgeEl = document.getElementById('player-count-badge');
        if (countBadgeEl) countBadgeEl.textContent = players.length;

        var playersSummaryEl = document.getElementById('players-summary');
        if (playersSummaryEl) playersSummaryEl.textContent = players.length;

        var playersEmptyEl = document.getElementById('players-empty');
        if (playersEmptyEl) playersEmptyEl.classList.toggle('hidden', players.length > 0);

        _renderHeroAndOrbits(players, data);
        updateAdminControls(players);
    }

    function handlePlayerLeft(data) {
        var players = data.players || [];

        var countBadgeEl = document.getElementById('player-count-badge');
        if (countBadgeEl) countBadgeEl.textContent = players.length;

        var playersSummaryEl = document.getElementById('players-summary');
        if (playersSummaryEl) playersSummaryEl.textContent = players.length;

        var playersEmptyEl = document.getElementById('players-empty');
        if (playersEmptyEl) playersEmptyEl.classList.toggle('hidden', players.length > 0);

        _renderHeroAndOrbits(players, data);
        updateAdminControls(players);
    }

    // ============================================
    // Invite Section (QR + Dashboard Link)
    // ============================================

    var currentJoinUrl = null;

    function setupInviteSection(joinUrl) {
        if (!joinUrl) return;
        currentJoinUrl = joinUrl;

        // Render QR code
        pu.generateQR('player-qr-code', joinUrl);

        // Set dashboard link
        var dashLink = document.getElementById('player-dashboard-url');
        if (dashLink) {
            dashLink.href = window.location.origin + '/quizify/dashboard';
        }

        // Make QR clickable to open modal
        var qrContainer = document.getElementById('player-qr-code');
        if (qrContainer) {
            qrContainer.onclick = openQRModal;
            qrContainer.onkeydown = function (e) {
                if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    openQRModal();
                }
            };
        }
    }

    // ============================================
    // QR Modal
    // ============================================

    function openQRModal() {
        if (!currentJoinUrl) return;

        var modal = document.getElementById('qr-modal');
        var modalCode = document.getElementById('qr-modal-code');
        if (!modal || !modalCode) return;

        modalCode.innerHTML = '';
        if (typeof QRCode !== 'undefined') {
            new QRCode(modalCode, {
                text: currentJoinUrl,
                width: 256,
                height: 256,
                colorDark: '#000000',
                colorLight: '#ffffff',
                correctLevel: QRCode.CorrectLevel.M
            });
        }

        modal.classList.remove('hidden');
        document.body.style.overflow = 'hidden';

        var closeBtn = document.getElementById('qr-modal-close');
        if (closeBtn) closeBtn.focus();
    }

    function closeQRModal() {
        var modal = document.getElementById('qr-modal');
        if (modal) {
            modal.classList.add('hidden');
            document.body.style.overflow = '';
        }
    }

    function setupQRModal() {
        var modal = document.getElementById('qr-modal');
        var backdrop = modal ? modal.querySelector('.qr-modal-backdrop') : null;
        var closeBtn = document.getElementById('qr-modal-close');

        if (backdrop) backdrop.addEventListener('click', closeQRModal);
        if (closeBtn) closeBtn.addEventListener('click', closeQRModal);

        document.addEventListener('keydown', function (e) {
            if (e.key === 'Escape' && modal && !modal.classList.contains('hidden')) {
                closeQRModal();
            }
        });
    }

    // ============================================
    // Invite Modal (in-game sharing)
    // ============================================

    function openInviteModal() {
        if (!currentJoinUrl) return;

        var modal = document.getElementById('invite-modal');
        var modalCode = document.getElementById('invite-modal-code');
        var urlInput = document.getElementById('invite-modal-url');
        if (!modal || !modalCode) return;

        modalCode.innerHTML = '';
        if (typeof QRCode !== 'undefined') {
            new QRCode(modalCode, {
                text: currentJoinUrl,
                width: 256,
                height: 256,
                colorDark: '#000000',
                colorLight: '#ffffff',
                correctLevel: QRCode.CorrectLevel.M
            });
        }

        if (urlInput) urlInput.value = currentJoinUrl;

        modal.classList.remove('hidden');
        document.body.style.overflow = 'hidden';

        var closeBtn = document.getElementById('invite-modal-close');
        if (closeBtn) closeBtn.focus();
    }

    function closeInviteModal() {
        var modal = document.getElementById('invite-modal');
        if (modal) {
            modal.classList.add('hidden');
            document.body.style.overflow = '';
        }
    }

    function copyJoinUrl() {
        var urlInput = document.getElementById('invite-modal-url');
        var feedback = document.getElementById('invite-copy-feedback');
        if (!urlInput || !currentJoinUrl) return;

        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(currentJoinUrl).then(function () {
                showCopyFeedback(feedback);
            }).catch(function () {
                fallbackCopy(urlInput, feedback);
            });
        } else {
            fallbackCopy(urlInput, feedback);
        }
    }

    function fallbackCopy(urlInput, feedback) {
        urlInput.select();
        urlInput.setSelectionRange(0, 99999);
        try {
            document.execCommand('copy');
            showCopyFeedback(feedback);
        } catch (e) {
            console.warn('[Quizify] Copy failed:', e);
        }
    }

    function showCopyFeedback(feedback) {
        if (!feedback) return;
        feedback.classList.remove('hidden');
        setTimeout(function () { feedback.classList.add('hidden'); }, 2000);
    }

    function setupInviteModal() {
        var modal = document.getElementById('invite-modal');
        var backdrop = modal ? modal.querySelector('.invite-modal-backdrop') : null;
        var closeBtn = document.getElementById('invite-modal-close');
        var inviteBtn = document.getElementById('invite-players-btn');
        var copyBtn = document.getElementById('invite-copy-btn');

        if (backdrop) backdrop.addEventListener('click', closeInviteModal);
        if (closeBtn) closeBtn.addEventListener('click', closeInviteModal);
        if (inviteBtn) inviteBtn.addEventListener('click', openInviteModal);
        if (copyBtn) copyBtn.addEventListener('click', copyJoinUrl);

        document.addEventListener('keydown', function (e) {
            if (e.key === 'Escape' && modal && !modal.classList.contains('hidden')) {
                closeInviteModal();
            }
        });
    }

    // ============================================
    // Admin Controls
    // ============================================

    function updateAdminControls(players) {
        var adminControls = document.getElementById('admin-controls');
        var lobbyStatus = document.getElementById('lobby-status');
        if (!adminControls) return;

        var currentPlayer = null;
        if (players && Array.isArray(players)) {
            for (var i = 0; i < players.length; i++) {
                if (players[i].name === state.playerName) {
                    currentPlayer = players[i];
                    break;
                }
            }
        }

        var playerIsAdmin = currentPlayer && currentPlayer.is_admin === true;
        state.isAdmin = playerIsAdmin;

        if (playerIsAdmin) {
            adminControls.classList.remove('hidden');
            if (lobbyStatus) lobbyStatus.classList.add('hidden');

            // Show start button when at least 1 player
            var startBtn = document.getElementById('start-game-btn');
            if (startBtn) {
                startBtn.disabled = players.length < 1;
            }
        } else {
            adminControls.classList.add('hidden');
            if (lobbyStatus) lobbyStatus.classList.remove('hidden');
        }
    }

    function setupAdminControls(sendFn) {
        var startBtn = document.getElementById('start-game-btn');
        if (startBtn) {
            startBtn.addEventListener('click', function () {
                if (!state.ws || state.ws.readyState !== WebSocket.OPEN) return;

                startBtn.disabled = true;
                startBtn.innerHTML = '<span class="btn-icon" aria-hidden="true">🎉</span><span>Starting...</span>';

                sendFn('start_game', {});
            });
        }
    }

    // ============================================
    // Init (called by core)
    // ============================================

    function init(sendFn) {
        setupQRModal();
        setupInviteModal();
        setupAdminControls(sendFn);
        pu.setupCollapsibles();
    }

    // ============================================
    // Export
    // ============================================

    window.QuizifyPlayerLobby = {
        init: init,
        renderLobby: renderLobby,
        handlePlayerJoined: handlePlayerJoined,
        handlePlayerLeft: handlePlayerLeft,
        setupInviteSection: setupInviteSection,
        updateAdminControls: updateAdminControls,
        closeInviteModal: closeInviteModal
    };

})();


/* ============ player-reveal.js ============ */

/**
 * Quizify Player - Reveal Module
 * Reveal phase: correct answer display, personal result, all answers grid, reactions
 */

(function () {
    'use strict';

    var pu = window.QuizifyPlayerUtils;
    var game = window.QuizifyPlayerGame;
    var state = pu.state;

    // Translation helper — falls back to the key if i18n hasn't loaded yet.
    // window.t is wired in i18n.js. The QuizifyUtils.t reference used to live
    // here didn't exist (QuizifyUtils only has escapeHtml), which is why
    // every "Final Results" / "Next Round" stayed in English on a German
    // game even though the keys existed in de.json.
    function t(key, params) {
        if (typeof window.t === 'function') return window.t(key, params);
        return key;
    }

    // Track the current question id so the 🚩 flag button knows what to send.
    var _currentQuestionId = '';
    var _flaggedThisRound = false;

    // ============================================
    // Reveal View Update
    // ============================================

    /**
     * Update reveal view with round results
     * @param {Object} data - State data from server
     */
    // Memo of the previous round's leaderboard so we can compute rank deltas
    // ("↑1", "↓1", "—") without server help. Keyed by lowercased player name.
    var _prevRanks = null;

    function updateRevealView(data) {
        var players = data.players || [];
        var allAnswers = data.all_answers || [];

        // Remember the question id and reset per-round flag state so the
        // 🚩 button knows what to POST and can be clicked again next round.
        _currentQuestionId = data.question_id || '';
        _flaggedThisRound = false;
        _resetFlagButton();

        // Find current player's entry in all_answers
        var myAnswerEntry = null;
        for (var i = 0; i < allAnswers.length; i++) {
            if (allAnswers[i].player_name === state.playerName) {
                myAnswerEntry = allAnswers[i];
                break;
            }
        }

        // Find current player in the leaderboard (has is_admin)
        var currentPlayer = null;
        for (var j = 0; j < players.length; j++) {
            if (players[j].name === state.playerName) {
                currentPlayer = players[j];
                break;
            }
        }

        // Round indicator — now lives inline next to the wordmark in
        // .player-header (moved from .pl-result-crown 2026-05-27).
        // Visibility is toggled by showView() in player-utils.js.
        var roundEl = document.getElementById('header-round-num');
        var totalEl = document.getElementById('header-round-total');
        if (roundEl) roundEl.textContent = data.round || 1;
        if (totalEl) totalEl.textContent = data.total_rounds || 10;

        // Fun fact
        renderFunFact(data.fun_fact);

        // Flash answer buttons correct/wrong. Per-player shuffle means
        // the server's `correct_answer_index` is in the CANONICAL shuffle
        // and doesn't match this player's button positions. We match by
        // text instead.
        flashAnswerButtons(data.correct_answer, myAnswerEntry);

        // New result page: hero + answer strip + standings (with medals)
        var resultPlayer = myAnswerEntry || currentPlayer;
        renderResultHero(resultPlayer, data);
        renderAnswerStrip(myAnswerEntry, data.correct_answer);
        renderStandings(data.leaderboard || players, state.playerName);

        // Audio cue on the player's own device: a chime when they got it
        // right, a buzzer when wrong. Skipped for players who joined late /
        // missed the round (no per-player result). Honours the mute toggle.
        playResultCue(resultPlayer);

        // Admin controls — sticky bottom bar
        var adminControls = document.getElementById('reveal-admin-controls');
        var nextRoundBtn = document.getElementById('next-round-btn');
        var isAdmin = !!(currentPlayer && currentPlayer.is_admin);
        if (document.body) document.body.classList.toggle('is-admin', isAdmin);
        if (adminControls) {
            if (isAdmin) adminControls.classList.remove('hidden');
            else adminControls.classList.add('hidden');
        }
        if (nextRoundBtn) {
            var nextLabel = nextRoundBtn.querySelector('[data-i18n]');
            if (data.last_round) {
                if (nextLabel) {
                    nextLabel.setAttribute('data-i18n', 'reveal.finalResults');
                    nextLabel.textContent = t('reveal.finalResults');
                }
                nextRoundBtn.classList.add('is-final');
            } else {
                if (nextLabel) {
                    nextLabel.setAttribute('data-i18n', 'admin.nextRound');
                    nextLabel.textContent = t('admin.nextRound');
                }
                nextRoundBtn.classList.remove('is-final');
            }
            nextRoundBtn.disabled = false;
        }
    }

    // ============================================
    // Fun Fact
    // ============================================

    /**
     * Render fun fact slide-in card
     * @param {string|null} text - Fun fact text
     */
    function renderAnswerDistribution(distribution, correctIndex, allAnswers, myAnswerEntry) {
        var container = document.getElementById('answer-distribution');
        if (!container) return;
        if (!distribution || distribution.length === 0) {
            container.classList.add('hidden');
            return;
        }

        // Build answer text map from allAnswers (keyed by ORIGINAL index, not
        // shuffled — per-player shuffle made shuffled index meaningless across
        // viewers, so we standardized on original at the server side).
        var answerTexts = {};
        if (allAnswers && allAnswers.length > 0) {
            allAnswers.forEach(function(a) {
                if (a.answer_index !== null && a.answer_index !== undefined && a.answer_text) {
                    answerTexts[a.answer_index] = a.answer_text;
                }
            });
        }

        // The player's own pick — used to render the "· DU" tag on their row
        // so they can find themselves even though their A/B/C buttons were in
        // a different order than the canonical distribution.
        var myIndex = (myAnswerEntry && typeof myAnswerEntry.answer_index === 'number')
            ? myAnswerEntry.answer_index
            : null;
        var youLabel = (typeof t === 'function' && t('lobby.you') !== 'lobby.you')
            ? t('lobby.you')
            : 'DU';

        var optionLabels = ['A', 'B', 'C', 'D'];

        // Variant F (Filling-Bar): each row IS the bar. Text + percentage sit
        // over a coral wash that grows from the left to the vote percentage.
        // Correct row paints sage with a ✓; the player's row appends "· DU"
        // in coral so finding yourself stays trivial under per-player shuffle.
        container.innerHTML = distribution
            .filter(function(d) { return !d.no_answer; })
            .map(function(d) {
                var isCorrect = d.index === correctIndex;
                var isMine = myIndex !== null && d.index === myIndex;
                var label = optionLabels[d.index] || String(d.index + 1);
                var text = answerTexts[d.index] || '';
                var pct = d.percent || 0;
                var classes = ['ad-row'];
                if (isCorrect) classes.push('ad-row--correct');
                if (isMine) classes.push('ad-row--mine');
                return '<div class="' + classes.join(' ') + '">' +
                    '<div class="ad-fill" style="width:' + pct + '%"></div>' +
                    '<div class="ad-content">' +
                        '<span class="ad-letter">' + label + (isCorrect ? ' ✓' : '') + '</span>' +
                        '<span class="ad-text">' +
                            pu.escapeHtml(text) +
                            (isMine ? '<span class="ad-mine"> · ' + pu.escapeHtml(youLabel) + '</span>' : '') +
                        '</span>' +
                        '<span class="ad-pct">' + pct + '%</span>' +
                    '</div>' +
                '</div>';
            }).join('');
        container.classList.remove('hidden');
    }

    function renderFunFact(text) {
        var container = document.getElementById('fun-fact-container');
        var funFactEl = document.getElementById('fun-fact');

        if (!container) return;

        if (text && text.trim()) {
            if (funFactEl) funFactEl.textContent = text;
            container.classList.remove('hidden');
        } else {
            container.classList.add('hidden');
        }
    }

    // ============================================
    // Result Hero — picks 1 of 4 states (Soft Parlor redesign, 2026-05-24):
    //   X = streak hero (≥2 correct in a row + this round correct)
    //   Y = big +N points (correct, streak < 2)
    //   Z = wrong  (soft brick verdict + 0)
    //   W = missed (muted clock + Zeit abgelaufen + 0)
    // ============================================

    var STREAK_HERO_THRESHOLD = 2;  // streak ≥ 2 promotes to the streak headline

    /**
     * Fire the correct/wrong audio cue for this player's round result.
     * Mirrors the verdict logic in renderResultHero (missed → no cue).
     * @param {Object} player - this player's result entry
     */
    function playResultCue(player) {
        var snd = window.QuizifyPlayerSound;
        if (!snd || !player) return;
        var missed = player.missed_round === true || player.no_answer === true ||
            player.answer_index === null || player.answer_index === undefined;
        if (missed) return;
        if (player.correct === true) snd.playCorrect();
        else snd.playWrong();
    }

    function renderResultHero(player, data) {
        var hero = document.getElementById('reveal-hero');
        if (!hero) return;

        hero.className = 'pl-result-hero';
        hero.innerHTML = '';

        // Joined late: server returns no per-player entry. Show a friendly note.
        if (!player) {
            hero.classList.add('pl-result-hero--missed');
            hero.innerHTML =
                '<span class="pl-result-verdict-circle pl-result-verdict-circle--missed" aria-hidden="true">👋</span>' +
                '<div class="pl-result-verdict">' + pu.escapeHtml(t('reveal.joinedLate')) + '</div>' +
                '<div class="pl-result-sub">' + pu.escapeHtml(t('reveal.joinedLateHint')) + '</div>';
            return;
        }

        var missed = player.missed_round === true || player.no_answer === true || player.answer_index === null || player.answer_index === undefined;
        var correct = player.correct === true;
        var streak = player.streak || player.new_streak || 0;
        var roundScore = player.round_score || player.points_earned || 0;
        var correctAnswer = (data && data.correct_answer) || '';

        // Score breakdown (used by states X and Y)
        var BASE_POINTS = 10;
        var baseScore = (typeof player.base_score === 'number') ? player.base_score : (correct ? BASE_POINTS : 0);
        var speedBonus = player.speed_bonus || 0;
        var streakBonus = player.streak_bonus || 0;
        var difficultyMult = player.difficulty_multiplier || 1.0;
        var breakdownBits = [];
        if (baseScore) breakdownBits.push(t('reveal.baseScore') + ' <b>' + baseScore + '</b>');
        if (speedBonus) breakdownBits.push(t('reveal.speedBonus') + ' <b>+' + speedBonus + '</b>');
        if (streakBonus) breakdownBits.push(t('reveal.streakBonus', { count: streak }) + ' <b>+' + streakBonus + '</b>');
        if (difficultyMult > 1.0) breakdownBits.push(t('reveal.difficulty') + ' <b>' + difficultyMult.toFixed(1) + 'x</b>');
        var breakdownHtml = breakdownBits.length
            ? '<div class="pl-result-breakdown">' + breakdownBits.join(' &middot; ') + '</div>'
            : '';

        if (missed) {
            // State W — muted clock + Zeit abgelaufen
            hero.classList.add('pl-result-hero--missed');
            hero.innerHTML =
                '<span class="pl-result-verdict-circle pl-result-verdict-circle--missed" aria-hidden="true">⏱</span>' +
                '<div class="pl-result-verdict">' + pu.escapeHtml(t('reveal.timeUp')) + '</div>' +
                '<div class="pl-result-sub">' + pu.escapeHtml(t('reveal.correctAnswerWas')) + ' <b>' + pu.escapeHtml(correctAnswer) + '</b></div>' +
                '<div class="pl-result-zero">0<span class="pl-result-zero-unit">' + pu.escapeHtml(t('game.points')) + '</span></div>';
            return;
        }

        if (!correct) {
            // State Z — wrong. Show "Serie verloren" only if a streak was active.
            var prevStreak = player.previous_streak || 0;
            hero.classList.add('pl-result-hero--wrong');
            hero.innerHTML =
                '<span class="pl-result-verdict-circle pl-result-verdict-circle--wrong" aria-hidden="true">✗</span>' +
                '<div class="pl-result-verdict">' + pu.escapeHtml(t('reveal.wrongHeadline')) + '</div>' +
                '<div class="pl-result-sub">' + pu.escapeHtml(t('reveal.correctAnswerWas')) + ' <b>' + pu.escapeHtml(correctAnswer) + '</b></div>' +
                '<div class="pl-result-zero">0<span class="pl-result-zero-unit">' + pu.escapeHtml(t('game.points')) + '</span></div>' +
                (prevStreak >= 2 ? '<div class="pl-result-streak-lost">💔 ' + pu.escapeHtml(t('reveal.streakLost', { count: prevStreak })) + '</div>' : '');
            return;
        }

        // Correct: pick X (streak) or Y (big)
        if (streak >= STREAK_HERO_THRESHOLD) {
            // State X — flame headline
            hero.classList.add('pl-result-hero--streak');
            hero.innerHTML =
                '<div class="pl-result-flame" aria-hidden="true">🔥</div>' +
                '<div class="pl-result-headline">' + pu.escapeHtml(t('reveal.streakHeadline', { count: streak })) + '</div>' +
                '<div class="pl-result-pts">+' + roundScore + '<span class="pl-result-pts-unit">' + pu.escapeHtml(t('game.points')) + '</span></div>' +
                breakdownHtml;
            return;
        }

        // State Y — big +N. Skip the green ✓ circle on correct answers:
        // the "+N PUNKTE" already reads as the positive verdict, and the
        // extra tick competes for attention with the points number.
        // Wrong answers (state Z) keep their ✗ so the negative outcome
        // is still unmistakable.
        hero.classList.add('pl-result-hero--big');
        hero.innerHTML =
            '<div class="pl-result-big-points">+' + roundScore + '</div>' +
            '<div class="pl-result-pts-unit">' + pu.escapeHtml(t('game.points').toUpperCase()) + '</div>' +
            breakdownHtml;
    }

    // ============================================
    // Answer strip — single line under the hero showing the correct answer
    // and a ✓/✗/— mark relative to what the player picked.
    // ============================================
    function renderAnswerStrip(myAnswer, correctAnswer) {
        var strip = document.getElementById('reveal-answer-strip');
        if (!strip) return;

        strip.className = 'pl-result-answer-strip';

        var ans = correctAnswer || '';
        var hasAnswer = myAnswer && myAnswer.answer_index !== null && myAnswer.answer_index !== undefined;
        var isCorrect = myAnswer && myAnswer.correct === true;

        if (!hasAnswer) {
            strip.classList.add('pl-result-answer-strip--missed');
            strip.innerHTML =
                '<span>' + pu.escapeHtml(t('reveal.noAnswerShort')) + '</span>' +
                '<span class="pl-result-answer-mark">—</span>';
            return;
        }

        if (isCorrect) {
            strip.innerHTML =
                '<span>' + pu.escapeHtml(t('reveal.answerLabel')) + ': <b>' + pu.escapeHtml(ans) + '</b></span>' +
                '<span class="pl-result-answer-mark">✓</span>';
            return;
        }

        // Wrong — show YOUR answer + the correct one in the sub area (already in hero), strip says "Deine Antwort"
        strip.classList.add('pl-result-answer-strip--wrong');
        var myText = myAnswer.answer_text || myAnswer.answer || '';
        strip.innerHTML =
            '<span>' + pu.escapeHtml(t('reveal.yourAnswer')) + ': <b>' + pu.escapeHtml(myText) + '</b></span>' +
            '<span class="pl-result-answer-mark">✗</span>';
    }

    // ============================================
    // Standings — top 3 with medal tints, "me" row with coral left border,
    // rank-delta arrows computed from the previous round's snapshot.
    // ============================================
    var _PLAYER_COLORS = ['#E88A7F','#7FA8C4','#7FA897','#E8C47F','#B78FC7','#D66A6A','#6E9685','#6A9AB6'];
    function _colorFor(name, idx) {
        // Stable color per name: hash first char, fall back to position.
        if (!name) return _PLAYER_COLORS[idx % _PLAYER_COLORS.length];
        var c = name.charCodeAt(0) || 0;
        return _PLAYER_COLORS[(c + idx) % _PLAYER_COLORS.length];
    }

    function renderStandings(leaderboard, myName) {
        var container = document.getElementById('reveal-standings');
        if (!container) return;

        // Normalize: leaderboard may be an array of player objects with
        // {name, score} or {player_name, total_score}. Sort by score desc.
        var rows = (Array.isArray(leaderboard) ? leaderboard : []).map(function(p) {
            var name = p.name || p.player_name || '';
            var score = (typeof p.score === 'number') ? p.score
                      : (typeof p.total_score === 'number') ? p.total_score
                      : (typeof p.points === 'number') ? p.points : 0;
            var color = p.color || null;
            return { name: name, score: score, color: color };
        });
        rows.sort(function(a, b) { return b.score - a.score; });

        // Build new rank map for next round's delta computation.
        var newRanks = {};
        rows.forEach(function(r, i) { newRanks[(r.name || '').toLowerCase()] = i + 1; });

        // Compute delta vs. previous round's snapshot (if any).
        function deltaFor(name) {
            if (!_prevRanks) return null;
            var key = (name || '').toLowerCase();
            var prev = _prevRanks[key];
            var now = newRanks[key];
            if (typeof prev !== 'number' || typeof now !== 'number') return null;
            return prev - now;  // positive = moved up
        }

        var medalClass = ['pl-result-srow--gold','pl-result-srow--silver','pl-result-srow--bronze'];
        var youLabel = t('lobby.you') !== 'lobby.you' ? t('lobby.you') : 'Du';

        container.innerHTML = rows.map(function(r, i) {
            var isMe = r.name === myName;
            var classes = ['pl-result-srow'];
            if (i < 3) classes.push(medalClass[i]);
            if (isMe) classes.push('pl-result-srow--me');
            var initial = (r.name || '?').charAt(0).toUpperCase();
            var bg = r.color || _colorFor(r.name, i);
            var displayName = isMe ? youLabel : (r.name || '');
            var d = deltaFor(r.name);
            var deltaHtml = '<span class="pl-result-delta pl-result-delta--flat">—</span>';
            if (d !== null) {
                if (d > 0) deltaHtml = '<span class="pl-result-delta pl-result-delta--up">↑' + d + '</span>';
                else if (d < 0) deltaHtml = '<span class="pl-result-delta pl-result-delta--down">↓' + Math.abs(d) + '</span>';
            }
            return '<div class="' + classes.join(' ') + '">' +
                '<span class="pl-result-pos">' + (i + 1) + '.</span>' +
                '<span class="pl-result-av" style="background:' + pu.escapeHtml(bg) + '">' + pu.escapeHtml(initial) + '</span>' +
                '<span class="pl-result-nm">' + pu.escapeHtml(displayName) + '</span>' +
                deltaHtml +
                '<span class="pl-result-sc">' + r.score + '</span>' +
            '</div>';
        }).join('');

        // Store snapshot for the NEXT round's delta computation.
        _prevRanks = newRanks;
    }

    // ============================================
    // Emotion Display
    // ============================================

    /**
     * Show celebration/disappointment emotion
     * @param {Object} player - Current player data
     */
    function renderRevealEmotion(player) {
        var emotionEl = document.getElementById('reveal-emotion');
        if (!emotionEl) return;

        emotionEl.innerHTML = '';
        emotionEl.className = 'reveal-emotion-inline';
        emotionEl.classList.add('hidden');

        if (!player) return;

        var correct = player.correct === true;
        var missed = player.missed_round === true || player.no_answer === true || player.answer_index === null;
        var streak = player.streak || player.new_streak || 0;
        var speedBonus = player.speed_bonus || 0;

        // All emotion strings live in i18n (reveal.emotion.*) so they
        // translate with the rest of the game. The arrays come back from
        // window.t verbatim because i18n values can be arrays.
        function pickFromKey(key, params) {
            var arr = t(key, params);
            if (!Array.isArray(arr)) return typeof arr === 'string' ? arr : '';
            return arr[Math.floor(Math.random() * arr.length)];
        }

        var emotionType, emotionText, subtitle;

        if (missed) {
            emotionType = 'missed';
            emotionText = pickFromKey('reveal.emotion.missed');
            subtitle = pickFromKey('reveal.emotion.missedSub');
        } else if (correct) {
            emotionType = 'exact';
            emotionText = pickFromKey('reveal.emotion.exact');
            if (streak >= 3) subtitle = pickFromKey('reveal.emotion.streakSub', { count: streak });
            else if (speedBonus > 200) subtitle = pickFromKey('reveal.emotion.fastSub');
            else subtitle = pickFromKey('reveal.emotion.exactSub');
        } else {
            emotionType = 'wrong';
            emotionText = pickFromKey('reveal.emotion.wrong');
            subtitle = pickFromKey('reveal.emotion.wrongSub');
        }

        var emotionHtml = '<span class="reveal-emotion-text">' + emotionText + '</span>';
        if (subtitle) {
            emotionHtml += '<div class="reveal-emotion-subtitle">' + subtitle + '</div>';
        }
        emotionEl.innerHTML = emotionHtml;
        emotionEl.classList.add('reveal-emotion--' + emotionType);
        emotionEl.classList.remove('hidden');

        // Broadcast Living Room: no confetti on correct-answer reveal.
        // The gold glow sweep on the correct tile (320ms ease-out) IS the celebration. See DESIGN.md.
    }

    // ============================================
    // Personal Result
    // ============================================

    /**
     * Render personal result in reveal view
     * @param {Object} player - Current player data
     */
    function renderPersonalResult(player) {
        var resultContent = document.getElementById('result-content');
        if (!resultContent) return;

        var ptsUnit = t('reveal.ptsUnit');

        if (!player) {
            resultContent.innerHTML =
                '<div class="result-missed-container">' +
                    '<div class="result-missed-icon">👋</div>' +
                    '<div class="result-missed-text">' + pu.escapeHtml(t('reveal.joinedLate')) + '</div>' +
                    '<div class="result-missed-text" style="font-size:0.8rem;opacity:0.6;">' + pu.escapeHtml(t('reveal.joinedLateHint')) + '</div>' +
                '</div>';
            return;
        }

        // Missed round (no answer)
        if (player.missed_round || player.no_answer || player.answer_index === null) {
            var prevStreak = player.streak || 0;
            var streakLostHtml = prevStreak > 1
                ? '<div class="result-row"><span class="result-label">' + pu.escapeHtml(t('reveal.streakLost', { count: prevStreak })) + '</span></div>'
                : '';
            resultContent.innerHTML =
                '<div class="result-missed-container">' +
                    '<div class="result-missed-icon">⏱️</div>' +
                    '<div class="result-missed-text">' + pu.escapeHtml(t('reveal.noAnswer')) + '</div>' +
                '</div>' +
                streakLostHtml +
                '<div class="result-score is-zero">0 ' + pu.escapeHtml(ptsUnit) + '</div>';
            return;
        }

        var isCorrect = player.correct === true;
        // BASE_POINTS in scoring.py is 10 — server may also send base_score
        // explicitly. Never invent a number (previous code hardcoded "1000 pts"
        // which never matched the real total below).
        var BASE_POINTS = 10;
        var baseScore = (typeof player.base_score === 'number') ? player.base_score : (isCorrect ? BASE_POINTS : 0);
        var speedBonus = player.speed_bonus || 0;
        var streakBonus = player.streak_bonus || 0;
        var difficultyMult = player.difficulty_multiplier || 1.0;
        var roundScore = player.round_score || player.points_earned || 0;
        var streak = player.streak || 0;
        var answerText = player.answer_text || player.answer || '?';

        // Score breakdown rows
        var breakdownHtml = '';
        if (isCorrect) {
            breakdownHtml +=
                '<div class="result-row">' +
                    '<span class="result-label">' + pu.escapeHtml(t('reveal.baseScore')) + '</span>' +
                    '<span class="result-value">' + baseScore + ' ' + pu.escapeHtml(ptsUnit) + '</span>' +
                '</div>';

            if (speedBonus > 0) {
                breakdownHtml +=
                    '<div class="result-row">' +
                        '<span class="result-label">' + pu.escapeHtml(t('reveal.speedBonus')) + '</span>' +
                        '<span class="result-value is-bonus">' + pu.escapeHtml(t('reveal.ptsBonus', { count: speedBonus })) + '</span>' +
                    '</div>';
            }

            if (difficultyMult > 1.0) {
                breakdownHtml +=
                    '<div class="result-row">' +
                        '<span class="result-label">' + pu.escapeHtml(t('reveal.difficulty')) + '</span>' +
                        '<span class="result-value is-bonus">' + difficultyMult.toFixed(1) + 'x</span>' +
                    '</div>';
            }
        }

        var streakHtml = '';
        if (streakBonus > 0) {
            streakHtml =
                '<div class="result-row streak-bonus-row">' +
                    '<span class="result-label">' + pu.escapeHtml(t('reveal.streakBonus', { count: streak })) + '</span>' +
                    '<span class="result-value is-streak">' + pu.escapeHtml(t('reveal.ptsBonus', { count: streakBonus })) + '</span>' +
                '</div>';
        } else if (streak > 1 && isCorrect) {
            streakHtml =
                '<div class="result-row streak-bonus-row">' +
                    '<span class="result-label">' + pu.escapeHtml(t('reveal.streakActive', { count: streak })) + '</span>' +
                '</div>';
        }

        resultContent.innerHTML =
            '<div class="result-row">' +
                '<span class="result-label">' + pu.escapeHtml(t('reveal.yourAnswer')) + '</span>' +
                '<span class="result-value">' + pu.escapeHtml(answerText) + '</span>' +
            '</div>' +
            '<div class="result-row">' +
                '<span class="result-label">' + pu.escapeHtml(t('reveal.result')) + '</span>' +
                '<span class="result-value ' + (isCorrect ? 'is-correct' : 'is-wrong') + '">' +
                    pu.escapeHtml(isCorrect ? t('reveal.correct') : t('reveal.wrong')) +
                '</span>' +
            '</div>' +
            breakdownHtml +
            '<div class="result-score ' + (roundScore > 0 ? 'is-score-high' : 'is-zero') + '">+<span id="result-score-value">0</span> ' + pu.escapeHtml(ptsUnit) + '</div>' +
            streakHtml;

        // Animate score counting up
        if (roundScore > 0) {
            var scoreEl = document.getElementById('result-score-value');
            if (scoreEl && pu.animateValue) {
                pu.animateValue(scoreEl, 0, roundScore, 600);
                // Floating popup
                setTimeout(function() {
                    if (pu.showPointsPopup) pu.showPointsPopup(scoreEl, roundScore);
                }, 100);
                // Streak popup after
                if (streakBonus > 0) {
                    setTimeout(function() {
                        if (pu.showPointsPopup) pu.showPointsPopup(scoreEl, streakBonus, { isStreak: true });
                    }, 500);
                }
            }
        }
    }

    // ============================================
    // All Answers Grid
    // ============================================

    /**
     * Render all player answers grid
     * @param {Array} players - All players from state
     */
    function renderAllAnswers(players) {
        var container = document.getElementById('reveal-results-cards');
        if (!container) return;

        if (!players || players.length === 0) {
            container.innerHTML = '';
            return;
        }

        var sorted = players.slice().sort(function (a, b) {
            return (b.round_score || 0) - (a.round_score || 0);
        });

        var html = '<div class="results-cards-scroll">';

        sorted.forEach(function (player) {
            var isCurrentPlayer = player.name === state.playerName;
            // Support both all_answers format and players format
            var isMissed = player.no_answer === true || player.missed_round === true || player.answer_index === null;
            var roundScore = player.points_earned || player.round_score || 0;
            var isCorrect = player.correct === true;

            var scoreClass = isMissed ? 'is-score-zero' :
                             isCorrect ? 'is-score-high' : 'is-score-zero';

            var answerDisplay = isMissed ? '—' : pu.escapeHtml(player.answer_text || player.answer || '?');
            var resultDisplay = isMissed ? ('⏱️ ' + pu.escapeHtml(t('admin.answerNone'))) :
                                isCorrect ? pu.escapeHtml(t('reveal.correct')) : pu.escapeHtml(t('reveal.wrong'));
            var youLabel = pu.escapeHtml(t('lobby.you') || 'You');

            html += '<div class="result-card ' + scoreClass + (isCurrentPlayer ? ' result-card--mine' : '') + '">' +
                '<div class="card-name">' + pu.escapeHtml(player.player_name || player.name) + (isCurrentPlayer ? ' <span class="you-badge">' + youLabel + '</span>' : '') + '</div>' +
                '<div class="card-guess">' + answerDisplay + '</div>' +
                '<div class="card-accuracy">' + resultDisplay + '</div>' +
                '<div class="card-score">+' + roundScore + '</div>' +
            '</div>';
        });

        html += '</div>';
        container.innerHTML = html;
    }

    // ============================================
    // Answer Button Flash
    // ============================================

    function flashAnswerButtons(correctAnswerText, myEntry) {
        var answerButtons = document.getElementById('answer-buttons');
        if (!answerButtons) return;

        var buttons = answerButtons.querySelectorAll('.answer-btn');
        if (!buttons.length) return;

        var mySubmittedIndex = game && game.getLastSubmittedIndex ? game.getLastSubmittedIndex() : -1;

        // Match by TEXT, not shuffled index. With per-player shuffles
        // the server's correct_answer_index would be in a different
        // shuffle than this player's buttons. The button text is the
        // ground truth that survives any reshuffling.
        function _buttonAnswerText(btn) {
            var span = btn.querySelector('.answer-btn-text, .answer-text, span');
            return (span ? span.textContent : btn.textContent || '').trim();
        }
        var correctText = (correctAnswerText || '').trim();

        buttons.forEach(function(btn, i) {
            var btnText = _buttonAnswerText(btn);
            btn.classList.remove('is-selected');

            if (correctText && btnText === correctText) {
                btn.classList.add('correct');
            } else if (i === mySubmittedIndex && (!myEntry || !myEntry.correct)) {
                btn.classList.add('wrong');
            } else {
                btn.classList.add('dimmed');
            }
        });

        if (myEntry && !myEntry.correct && mySubmittedIndex >= 0) {
            var wrongBtn = buttons[mySubmittedIndex];
            if (wrongBtn) { wrongBtn.classList.remove('dimmed'); wrongBtn.classList.add('wrong'); }
        }
    }

    // ============================================
    // Flag question (🚩)
    // ============================================
    //
    // POSTs the current question's id to /api/quizify/flag-question so the
    // pack maintainer can triage ambiguous or wrong answers later. Reset
    // each round so a player can't spam-flag.

    function _resetFlagButton() {
        var btn = document.getElementById('flag-question-btn');
        if (btn) {
            btn.disabled = false;
            btn.textContent = '🚩';
            btn.classList.remove('is-flagged');
        }
    }

    function _wireFlagButton() {
        var btn = document.getElementById('flag-question-btn');
        if (!btn || btn._wired) return;
        btn._wired = true;
        btn.addEventListener('click', function () {
            if (_flaggedThisRound || !_currentQuestionId) return;
            _flaggedThisRound = true;
            btn.disabled = true;
            btn.textContent = '✓';
            btn.classList.add('is-flagged');
            fetch('/api/quizify/flag-question', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    question_id: _currentQuestionId,
                    player_name: state.playerName || '',
                    reason: '',
                }),
            }).then(function (r) {
                if (!r.ok) throw new Error('flag failed: ' + r.status);
                pu.showToast(t('reveal.flagThanks'), 1800);
            }).catch(function (err) {
                console.warn('[Quizify] flag error', err);
                // Re-enable so the user can retry.
                _flaggedThisRound = false;
                _resetFlagButton();
            });
        });
    }

    // Wire once the module loads — the button lives in player.html.
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', _wireFlagButton);
    } else {
        _wireFlagButton();
    }

    // ============================================
    // Export
    // ============================================

    window.QuizifyPlayerReveal = {
        updateRevealView: updateRevealView,
        renderFunFact: renderFunFact,
        renderRevealEmotion: renderRevealEmotion,
        renderPersonalResult: renderPersonalResult,
        renderAllAnswers: renderAllAnswers
    };

})();


/* ============ player-end.js ============ */

/**
 * Quizify Player - End Module
 * End screen: podium, superlatives, share card, full leaderboard, new-game
 */

(function () {
    'use strict';

    var pu = window.QuizifyPlayerUtils;
    var utils = window.QuizifyUtils || {};
    var state = pu.state;

    function _t(key, params) {
        if (window.QuizifyI18n && typeof window.QuizifyI18n.t === 'function') {
            return window.QuizifyI18n.t(key, params);
        }
        return key;
    }

    // ============================================
    // End View
    // ============================================

    /**
     * Update end view with final standings and stats
     * @param {Object} data - State data with leaderboard and game_stats
     */
    function updateEndView(data) {
        window.scrollTo(0, 0);
        var leaderboard = data.leaderboard || [];

        leaderboard.forEach(function (entry) {
            entry.is_current = (entry.name === state.playerName);
        });

        // Podium (positions 1, 2, 3)
        renderFinale(leaderboard);

        // Your result
        var currentPlayer = leaderboard.find(function (p) { return p.is_current; });
        renderYourResult(currentPlayer, data);

        // Full leaderboard
        renderFullLeaderboard(leaderboard);

        // Superlatives
        renderSuperlatives(data.superlatives);

        // Highlights
        renderHighlights(leaderboard);

        // Admin / player controls.
        //
        // Source-of-truth: trust ``state.isAdmin`` for gating the
        // host-only "Start New Game" button. Earlier versions only
        // looked at ``currentPlayer.is_admin`` from the leaderboard,
        // which created a chronic lockout: when a player joined while
        // the server was already in FINALE, the snapshot's leaderboard
        // (built by ``state.get_leaderboard()``) didn't include
        // ``is_admin`` per row, so the admin's button stayed hidden.
        // ``state.isAdmin`` is set from the URL ``?admin=true`` flag
        // and confirmed by the server's ``joined`` reply. v1.1.4 also
        // restores ``is_admin`` to the snapshot leaderboard, so either
        // signal is now sufficient — but local state is authoritative.
        var adminControls = document.getElementById('end-admin-controls');
        var playerMessage = document.getElementById('end-player-message');
        var amAdmin = !!state.isAdmin || !!(currentPlayer && currentPlayer.is_admin);

        if (amAdmin) {
            if (adminControls) adminControls.classList.remove('hidden');
            if (playerMessage) playerMessage.classList.add('hidden');
        } else {
            if (adminControls) adminControls.classList.add('hidden');
            if (playerMessage) playerMessage.classList.remove('hidden');
        }

        // Broadcast Living Room: no confetti on finale.
        // The restraint is the differentiation. A single spotlight and tabular score-tick IS the effect.
        // See DESIGN.md — "The dramatic pause IS the effect. Restraint crowns louder than chaos."
    }

    // ============================================
    // Podium / Finale
    // ============================================

    /**
     * Animate podium rise: 2nd, then 1st, then 3rd (Beatify order)
     * @param {Array} leaderboard - Sorted leaderboard
     */
    function renderFinale(leaderboard) {
        // Update podium places
        [1, 2, 3].forEach(function (place) {
            var player = leaderboard.find(function (p) { return p.rank === place; });
            var nameEl = document.getElementById('podium-' + place + '-name');
            var scoreEl = document.getElementById('podium-' + place + '-score');
            if (nameEl) nameEl.textContent = player ? pu.escapeHtml(player.name) : '---';
            if (scoreEl) scoreEl.textContent = player ? player.score : '0';
        });

        // Champion title block: fill the winner's name under "Champion".
        var champEl = document.getElementById('podium-champion-name');
        if (champEl) {
            var champion = leaderboard.find(function (p) { return p.rank === 1; });
            champEl.textContent = champion ? pu.escapeHtml(champion.name) : '---';
        }

        // Animate podium rise with delays: 2nd (0s), 1st (1s), 3rd (2s)
        var podiumPlaces = document.querySelectorAll('.podium-place');
        podiumPlaces.forEach(function (el) {
            el.classList.remove('podium-rise');
        });

        // 2nd place rises first
        var place2 = document.querySelector('.podium-2');
        if (place2) {
            setTimeout(function () { place2.classList.add('podium-rise'); }, 300);
        }

        // 1st place rises second
        var place1 = document.querySelector('.podium-1');
        if (place1) {
            setTimeout(function () { place1.classList.add('podium-rise'); }, 1300);
        }

        // 3rd place rises last
        var place3 = document.querySelector('.podium-3');
        if (place3) {
            setTimeout(function () { place3.classList.add('podium-rise'); }, 2300);
        }
    }

    // ============================================
    // Your Result
    // ============================================

    /**
     * Render personal final result
     * @param {Object} currentPlayer - Current player leaderboard entry
     * @param {Object} data - Full state data
     */
    function renderYourResult(currentPlayer, data) {
        var rankEl = document.getElementById('your-final-rank');
        var scoreEl = document.getElementById('your-final-score');
        var bestStreakEl = document.getElementById('stat-best-streak');
        var roundsEl = document.getElementById('stat-rounds');
        var powerupsEl = document.getElementById('stat-powerups');

        if (currentPlayer) {
            if (rankEl) rankEl.textContent = '#' + currentPlayer.rank;
            if (scoreEl) scoreEl.textContent = _t('game.pointsLabel', { count: currentPlayer.score });
            if (bestStreakEl) bestStreakEl.textContent = currentPlayer.best_streak || 0;
            if (roundsEl) roundsEl.textContent = currentPlayer.rounds_played || 0;
            if (powerupsEl) powerupsEl.textContent = currentPlayer.powerups_used || 0;
        }
    }

    // ============================================
    // Full Leaderboard
    // ============================================

    /**
     * Render numbered leaderboard with scores
     * @param {Array} leaderboard - Full sorted leaderboard
     */
    function renderFullLeaderboard(leaderboard) {
        var listEl = document.getElementById('final-leaderboard-list');
        if (!listEl) return;

        // Ranked Bars: each row carries a faint sage bar scaled to the
        // player's score, so the gaps between players read at a glance.
        // Top-3 ranks get a medal-tinted dot; the current player's row gets
        // a coral left border.
        var maxScore = leaderboard.reduce(function (m, e) {
            return Math.max(m, e.score || 0);
        }, 0) || 1;
        var MEDAL_DOTS = { 1: 'lb-mdot--gold', 2: 'lb-mdot--silver', 3: 'lb-mdot--bronze' };

        listEl.innerHTML = leaderboard.map(function (entry) {
            var currentClass = entry.is_current ? 'is-current' : '';
            var disconnectedClass = entry.connected === false ? 'final-entry--disconnected' : '';
            var awayBadge = entry.connected === false
                ? '<span class="away-badge">(' + pu.escapeHtml(_t('lobby.away') !== 'lobby.away' ? _t('lobby.away') : 'away') + ')</span>'
                : '';
            var pct = Math.max(8, Math.round(((entry.score || 0) / maxScore) * 100));
            var medalDot = MEDAL_DOTS[entry.rank]
                ? '<span class="lb-mdot ' + MEDAL_DOTS[entry.rank] + '"></span>'
                : '';
            return '<div class="final-entry ' + currentClass + ' ' + disconnectedClass + '">' +
                '<span class="final-rank">' + entry.rank + '</span>' +
                '<div class="final-track">' +
                    '<div class="final-fill" style="width:' + pct + '%"></div>' +
                    '<span class="final-name">' + medalDot + pu.escapeHtml(entry.name) + awayBadge + '</span>' +
                '</div>' +
                '<span class="final-score">' + entry.score + '</span>' +
            '</div>';
        }).join('');
    }

    // ============================================
    // Superlatives
    // ============================================

    /**
     * Render superlatives / fun awards with staggered entrance
     * @param {Array|null} superlatives - Array of award objects
     */
    function renderSuperlatives(superlatives) {
        var container = document.getElementById('superlatives-container');
        if (!container) return;

        if (!superlatives || superlatives.length === 0) {
            container.classList.add('hidden');
            return;
        }

        // Trophy Tiles: 2-col grid of square cards, each with the award glyph
        // in a rotating colored disc (coral/sage/sky/sun across the palette).
        var DISC_TINTS = ['sup-disc--coral', 'sup-disc--sage', 'sup-disc--sky', 'sup-disc--sun'];
        var cards = '';
        superlatives.forEach(function (award, index) {
            // Server format: {award, icon, winner, detail, award_key, detail_key, detail_params}
            // Legacy format: {title, emoji, player_name, value}
            var emoji = award.icon || award.emoji || '🏆';
            // Prefer i18n keys if the server sent them; fall back to English literals.
            var titleKey = award.award_key;
            var detailKey = award.detail_key;
            var detailParams = award.detail_params || {};
            var title = titleKey ? _t(titleKey) : (award.award || award.title || '');
            // If _t returned the key unchanged (missing translation), keep the
            // English literal as a fallback so we never show "highlights.awards.x".
            if (titleKey && title === titleKey) title = award.award || award.title || '';
            var player = award.winner || award.player_name || '';
            var detail = detailKey ? _t(detailKey, detailParams) : (award.detail || award.value || '');
            if (detailKey && detail === detailKey) detail = award.detail || award.value || '';

            var tint = DISC_TINTS[index % DISC_TINTS.length];
            cards += '<div class="superlative-card" style="animation-delay: ' + (index * 0.2) + 's">' +
                '<div class="superlative-disc ' + tint + '">' + emoji + '</div>' +
                '<div class="superlative-title">' + pu.escapeHtml(title) + '</div>' +
                '<div class="superlative-player">' + pu.escapeHtml(player) + '</div>' +
                '<div class="superlative-value">' + pu.escapeHtml(String(detail)) + '</div>' +
            '</div>';
        });

        container.innerHTML =
            '<div class="superlatives-header" data-i18n="leaderboard.awardsHeader">' +
                pu.escapeHtml(_t('leaderboard.awardsHeader') !== 'leaderboard.awardsHeader' ? _t('leaderboard.awardsHeader') : 'Auszeichnungen') +
            '</div>' +
            '<div class="superlatives-grid">' + cards + '</div>';
        container.classList.remove('hidden');
    }

    // ============================================
    // Highlights
    // ============================================

    function renderHighlights(leaderboard) {
        var container = document.getElementById('highlights-container');
        var listEl = document.getElementById('highlights-list');
        if (!container || !listEl) return;
        if (!leaderboard || leaderboard.length < 2) { container.classList.add('hidden'); return; }

        var highlights = [];

        // Top scorer this game
        var winner = leaderboard[0];
        if (winner) highlights.push({
            icon: '🥇',
            label: _t('highlights.topScore'),
            player: winner.name,
            value: _t('highlights.scoreUnit', { count: winner.score }),
        });

        // Longest streak
        var streakLeader = leaderboard.slice().sort(function(a,b){ return (b.streak||0)-(a.streak||0); })[0];
        if (streakLeader && streakLeader.streak > 1) {
            highlights.push({
                icon: '🔥',
                label: _t('highlights.bestStreak'),
                player: streakLeader.name,
                value: _t('highlights.streakUnit', { count: streakLeader.streak }),
            });
        }

        // Most rounds correct (from round_history if available)
        var mostCorrect = leaderboard.slice().sort(function(a,b){
            var ac = (a.rounds_correct || 0); var bc = (b.rounds_correct || 0);
            return bc - ac;
        })[0];
        if (mostCorrect && mostCorrect.rounds_correct > 0) {
            highlights.push({
                icon: '🎯',
                label: _t('highlights.mostCorrect'),
                player: mostCorrect.name,
                value: _t('highlights.correctUnit', { count: mostCorrect.rounds_correct }),
            });
        }

        if (highlights.length === 0) { container.classList.add('hidden'); return; }

        // Vertical Timeline: a sage spine with a rotating-color dot per moment,
        // each card branching to the right. Reads top-to-bottom as the story
        // of the game.
        var DOT_TINTS = ['hl-dot--coral', 'hl-dot--sage', 'hl-dot--sky', 'hl-dot--sun'];
        listEl.innerHTML = highlights.map(function(h, i) {
            var tint = DOT_TINTS[i % DOT_TINTS.length];
            return '<div class="highlight-item" style="animation-delay:' + (i * 0.15) + 's">' +
                '<span class="highlight-dot ' + tint + '"></span>' +
                '<div class="highlight-card">' +
                    '<div class="highlight-label">' + pu.escapeHtml(h.label) + '</div>' +
                    '<div class="highlight-player">' + pu.escapeHtml(h.player) + '</div>' +
                    '<div class="highlight-value">' + pu.escapeHtml(h.value) + '</div>' +
                '</div>' +
            '</div>';
        }).join('');
        container.classList.remove('hidden');
    }

    // ============================================
    // Admin Actions
    // ============================================

    // Rematch button removed in v1.1.3. Hosts always start a fresh
    // game from the admin URL (which also resets player session
    // tokens). Keeping a single primary CTA on the finale screen
    // simplifies the host's mental model — there's exactly one
    // post-game action.

    /**
     * Wire up the finale CTAs.
     *
     * Two buttons:
     *   - Wieder spielen (same settings): single-tap rematch. Server keeps
     *     players + scores zeroed, reuses the cached settings. The admin
     *     stays on /quizify/player and just waits for the next round.
     *   - Neues Spiel: full reset — back to /quizify/admin setup screen.
     */
    function setupNewGameButton() {
        var playAgainBtn = document.getElementById('play-again-same-btn');
        var newGameBtn = document.getElementById('new-game-btn');

        if (playAgainBtn) {
            playAgainBtn.onclick = function () {
                var ws = state.ws;
                if (!ws || ws.readyState !== WebSocket.OPEN) {
                    // Fall back to full reset if our WS is gone.
                    if (newGameBtn) newGameBtn.click();
                    return;
                }
                playAgainBtn.disabled = true;
                playAgainBtn.innerHTML = '<span>⏳</span>';
                try { ws.send(JSON.stringify({ type: 'play_again' })); } catch (e) { /* ignore */ }
                // Server will broadcast game_state QUESTION_ACTIVE → the
                // phase router in player-core picks it up and switches
                // views. No navigation needed.
            };
        }

        // Lightning Round trigger from the finale (issue #42). Sends
        // start_lightning over the existing WS — server transitions into
        // the LIGHTNING phase and the phase router swaps views. No
        // navigation needed (admin is already on /quizify/player).
        var lightningBtn = document.getElementById('lightning-from-end-btn');
        if (lightningBtn) {
            lightningBtn.onclick = function () {
                var ws = state.ws;
                if (!ws || ws.readyState !== WebSocket.OPEN) return;
                lightningBtn.disabled = true;
                try { ws.send(JSON.stringify({ type: 'start_lightning' })); } catch (e) { /* ignore */ }
            };
        }

        if (newGameBtn) {
            newGameBtn.onclick = function () {
                try {
                    sessionStorage.removeItem('quizify_session_token');
                    sessionStorage.removeItem('quizify_player_name');
                    sessionStorage.removeItem('quizify_admin_name');
                    sessionStorage.removeItem('quizify_is_admin');
                } catch (e) { /* ignore */ }

                var ws = state.ws;
                if (ws && ws.readyState === WebSocket.OPEN) {
                    try { ws.send(JSON.stringify({ type: 'reset_game' })); } catch (e) { /* ignore */ }
                }
                window.location.href = '/quizify/admin';
            };
        }
    }

    // ============================================
    // Export
    // ============================================

    window.QuizifyPlayerEnd = {
        updateEndView: updateEndView,
        renderFinale: renderFinale,
        renderYourResult: renderYourResult,
        renderFullLeaderboard: renderFullLeaderboard,
        renderSuperlatives: renderSuperlatives,
        setupNewGameButton: setupNewGameButton,
        renderHighlights: renderHighlights
    };

})();


/* ============ player-lightning.js ============ */

/**
 * Quizify Player - Lightning Round Module (issue #42)
 *
 * Renders the fast lightning question view + the end recap grid. The mode
 * has NO reveal between questions, fixed points per correct answer, and
 * power-ups disabled — so this module is intentionally light: show the
 * question, let the player tap once, lock the buttons, wait for the next
 * one to be pushed by the server.
 *
 * Core (player-core.js) injects its `send` function via setSend() so we
 * don't need our own WebSocket handle.
 */
(function () {
    'use strict';

    var pu = window.QuizifyPlayerUtils;
    var state = pu.state;

    var _send = function () {};
    function setSend(fn) { _send = fn; }

    function t(key, vars) {
        var fn = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
        return fn(key, vars);
    }

    var _answeredIndex = -1; // server question index we've answered

    // ------------------------------------------------------------------
    // Intro splash (issue #201 — "Bolt Burst")
    // ------------------------------------------------------------------

    function handleLightningSplash(msg) {
        msg = msg || {};
        pu.showView('lightning-splash-view');

        var countEl = document.getElementById('lightning-splash-count');
        if (countEl && typeof msg.num_questions === 'number') {
            countEl.textContent = msg.num_questions;
        }
        var secEl = document.getElementById('lightning-splash-seconds');
        if (secEl && typeof msg.seconds_per_question === 'number') {
            secEl.textContent = Math.round(msg.seconds_per_question) + 's';
        }

        // Admin gets the Start footer bar; players get the waiting hint.
        var adminBar = document.getElementById('lightning-splash-adminbar');
        var waitHint = document.getElementById('lightning-splash-waithint');
        if (adminBar) adminBar.classList.toggle('hidden', !state.isAdmin);
        if (waitHint) waitHint.classList.toggle('hidden', !!state.isAdmin);

        var startBtn = document.getElementById('lightning-splash-start-btn');
        if (startBtn) startBtn.disabled = false;
    }

    // ------------------------------------------------------------------
    // Question render
    // ------------------------------------------------------------------

    function handleLightningQuestion(msg) {
        pu.showView('lightning-view');

        var prog = document.getElementById('lightning-progress');
        if (prog) prog.textContent = ((msg.index || 0) + 1) + ' / ' + (msg.num_questions || 5);

        var cat = document.getElementById('lightning-category');
        if (cat) cat.textContent = msg.category || '';

        var img = document.getElementById('lightning-image');
        if (img) {
            if (msg.image_url) { img.src = msg.image_url; img.hidden = false; }
            else { img.hidden = true; img.removeAttribute('src'); }
        }

        var qtext = document.getElementById('lightning-question-text');
        if (qtext) qtext.textContent = msg.question_text || '';

        var answers = msg.answers || [];
        for (var i = 0; i < 3; i++) {
            var span = document.getElementById('lightning-answer-text-' + i);
            var btn = document.querySelector('[data-lightning-answer="' + i + '"]');
            if (span) span.textContent = answers[i] || '';
            if (btn) {
                btn.disabled = false;
                btn.classList.remove('answer-btn--correct', 'answer-btn--wrong', 'selected');
                btn.style.visibility = (i < answers.length) ? '' : 'hidden';
            }
        }

        var answered = document.getElementById('lightning-answered');
        if (answered) answered.classList.add('hidden');

        var timer = document.getElementById('lightning-timer');
        if (timer) timer.textContent = Math.ceil(msg.seconds || 15);

        // Admin gets an "end now" control.
        var adminBar = document.getElementById('lightning-admin-bar');
        if (adminBar) adminBar.classList.toggle('hidden', !state.isAdmin);

        _answeredIndex = -1;
    }

    function handleLightningTick(msg) {
        var timer = document.getElementById('lightning-timer');
        if (timer && typeof msg.remaining === 'number') {
            timer.textContent = Math.ceil(msg.remaining);
        }
    }

    function submitAnswer(shuffledIndex) {
        // One answer per question; ignore re-taps.
        if (_answeredIndex !== -1) return;
        _answeredIndex = shuffledIndex;
        _send('lightning_answer', { answer_index: shuffledIndex });

        // Lock buttons + mark the chosen one. No correctness shown until
        // the recap (no reveal between questions) — except the lightweight
        // ack flips a subtle state via handleLightningAnswerResult.
        var btns = document.querySelectorAll('[data-lightning-answer]');
        for (var i = 0; i < btns.length; i++) {
            btns[i].disabled = true;
            if (parseInt(btns[i].getAttribute('data-lightning-answer'), 10) === shuffledIndex) {
                btns[i].classList.add('selected');
            }
        }
        var answered = document.getElementById('lightning-answered');
        if (answered) answered.classList.remove('hidden');
    }

    function handleLightningAnswerResult(msg) {
        // Optional subtle feedback on the player's own button (still no
        // "the right answer was X" — that's reserved for the recap).
        var scoreEl = document.getElementById('lightning-score');
        if (scoreEl && typeof msg.score === 'number') scoreEl.textContent = msg.score;
    }

    // ------------------------------------------------------------------
    // Recap render
    // ------------------------------------------------------------------

    function handleLightningRecap(msg) {
        pu.showView('lightning-recap-view');
        var recap = msg.recap || (msg.lightning_recap) || {};
        renderRecap(recap);

        var adminCtl = document.getElementById('lightning-recap-admin');
        var playerMsg = document.getElementById('lightning-recap-player-msg');
        if (adminCtl) adminCtl.classList.toggle('hidden', !state.isAdmin);
        if (playerMsg) playerMsg.classList.toggle('hidden', !!state.isAdmin);
    }

    function renderRecap(recap) {
        var lb = recap.leaderboard || [];
        var lbEl = document.getElementById('lightning-recap-leaderboard');
        if (lbEl) {
            lbEl.innerHTML = lb.map(function (p) {
                var you = (p.name === state.playerName)
                    ? ' <span class="you-badge">(you)</span>' : '';
                return '<div class="final-leaderboard-row">' +
                    '<span class="rank">#' + p.rank + '</span>' +
                    '<span class="name">' + pu.escapeHtml(p.name) + you + '</span>' +
                    '<span class="score">' + p.score + '</span>' +
                    '</div>';
            }).join('');
        }

        // Per-question recap rows (Variant C refined): one row per question,
        // focused on THIS player. Always shows the correct answer (green);
        // when the player answered wrong, also shows their own wrong pick.
        var grid = document.getElementById('lightning-recap-grid');
        if (grid) {
            var me = state.playerName;
            var questions = recap.questions || [];
            grid.innerHTML = questions.map(function (q, qi) {
                var result = (q.results || {})[me] || 'miss';
                var ok = result === 'correct';
                var rowCls = ok ? 'lr-recap-row ok' : 'lr-recap-row no';
                var badge = ok ? '✓' : '✗'; // ✓ / ✗

                var html = '<div class="' + rowCls + '">' +
                    '<span class="lr-recap-badge">' + badge + '</span>' +
                    '<div class="lr-recap-body">' +
                        '<div class="lr-recap-q">' +
                            '<span class="lr-recap-qnum">' + (qi + 1) + '.</span> ' +
                            pu.escapeHtml(q.question_text) +
                        '</div>' +
                        '<div class="lr-recap-correct">' +
                            '<span class="lr-recap-tag" data-i18n="lightning.correctTag">' +
                            pu.escapeHtml(t('lightning.correctTag')) + '</span>' +
                            pu.escapeHtml(q.correct_answer) +
                        '</div>';

                // Player answered wrong → surface their pick.
                if (!ok && result === 'wrong') {
                    var chosen = (q.chosen || {})[me];
                    if (chosen) {
                        html += '<div class="lr-recap-yours">' +
                            '<span class="lr-recap-tag" data-i18n="lightning.youSaidTag">' +
                            pu.escapeHtml(t('lightning.youSaidTag')) + '</span>' +
                            pu.escapeHtml(chosen) +
                            '</div>';
                    }
                }

                html += '</div></div>';
                return html;
            }).join('');
        }
    }

    // ------------------------------------------------------------------
    // Wiring
    // ------------------------------------------------------------------

    function init() {
        var btns = document.querySelectorAll('[data-lightning-answer]');
        for (var i = 0; i < btns.length; i++) {
            (function (idx) {
                btns[idx].addEventListener('click', function () {
                    submitAnswer(parseInt(this.getAttribute('data-lightning-answer'), 10));
                });
            })(i);
        }
        var splashStartBtn = document.getElementById('lightning-splash-start-btn');
        if (splashStartBtn) {
            splashStartBtn.addEventListener('click', function () {
                this.disabled = true;  // one-shot; avoid double-fire
                _send('start_lightning_questions', {});
            });
        }

        var endBtn = document.getElementById('lightning-end-btn');
        if (endBtn) endBtn.addEventListener('click', function () { _send('end_lightning', {}); });

        var againBtn = document.getElementById('lightning-recap-again-btn');
        if (againBtn) againBtn.addEventListener('click', function () { _send('start_lightning', {}); });
        var newGameBtn = document.getElementById('lightning-recap-newgame-btn');
        if (newGameBtn) newGameBtn.addEventListener('click', function () { _send('reset_game', {}); });
    }

    window.QuizifyPlayerLightning = {
        setSend: setSend,
        init: init,
        handleLightningSplash: handleLightningSplash,
        handleLightningQuestion: handleLightningQuestion,
        handleLightningTick: handleLightningTick,
        handleLightningAnswerResult: handleLightningAnswerResult,
        handleLightningRecap: handleLightningRecap,
        renderRecap: renderRecap
    };
})();


/* ============ player-game.js ============ */

/**
 * Quizify Player - Game Module
 * Playing phase: question display, answer submission, timer, power-ups, leaderboard
 */

(function () {
    'use strict';

    var pu = window.QuizifyPlayerUtils;
    var utils = window.QuizifyUtils || {};
    var state = pu.state;

    // ============================================
    // Countdown Timer
    // ============================================

    var countdownInterval = null;

    /**
     * Start countdown timer
     * @param {number} deadline - Server deadline timestamp in milliseconds
     */
    function startCountdown(deadline) {
        stopCountdown();
        if (window.QuizifyPlayerSound) window.QuizifyPlayerSound.resetTick();

        var timerElement = document.getElementById('timer');
        if (!timerElement) return;

        timerElement.classList.remove('timer--warning', 'timer--critical');

        function updateCountdown() {
            var now = Date.now();
            var remaining = Math.max(0, Math.ceil((deadline - now) / 1000));

            timerElement.textContent = remaining;

            // Soft tick in the last 5 seconds (one per whole second).
            if (window.QuizifyPlayerSound) window.QuizifyPlayerSound.tickFromRemaining(remaining);

            if (remaining <= 5) {
                timerElement.classList.remove('timer--warning');
                timerElement.classList.add('timer--critical');
            } else if (remaining <= 10) {
                timerElement.classList.remove('timer--critical');
                timerElement.classList.add('timer--warning');
            } else {
                timerElement.classList.remove('timer--warning', 'timer--critical');
            }

            var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
            timerElement.setAttribute('aria-label', t('game.timerRemainingAria', { seconds: remaining }));

            if (remaining <= 0) {
                timerElement.setAttribute('aria-label', t('game.timerUpAria'));
                stopCountdown();
            }
        }

        updateCountdown();
        countdownInterval = setInterval(updateCountdown, 1000);
    }

    /**
     * Stop countdown timer
     */
    function stopCountdown() {
        if (countdownInterval) {
            clearInterval(countdownInterval);
            countdownInterval = null;
        }
    }

    /**
     * Update timer from server tick
     * @param {number} remaining - Remaining seconds
     */
    function updateTimer(remaining) {
        var timerElement = document.getElementById('timer');
        if (!timerElement) return;

        // Server sends decimals (e.g. 19.5) for smoother bar animations;
        // display as a whole-second integer so the count text reads cleanly.
        var displaySeconds = Math.ceil(remaining);
        timerElement.textContent = displaySeconds;

        // Soft tick in the last 5 seconds (one per whole second).
        if (window.QuizifyPlayerSound) window.QuizifyPlayerSound.tickFromRemaining(remaining);

        if (remaining <= 5) {
            timerElement.classList.remove('timer--warning');
            timerElement.classList.add('timer--critical');
        } else if (remaining <= 10) {
            timerElement.classList.remove('timer--critical');
            timerElement.classList.add('timer--warning');
        } else {
            timerElement.classList.remove('timer--warning', 'timer--critical');
        }

        var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
        timerElement.setAttribute('aria-label', t('game.timerRemainingAria', { seconds: displaySeconds }));
    }

    // ============================================
    // Question Rendering
    // ============================================

    /**
     * Render question text and answer buttons
     * @param {Object} data - Question data with text, answers, category
     */
    // Wager gate (gameplay idea #3). On the final round we block the
    // answer buttons until the player submits a wager. Without this
    // gate the player could just tap their answer instantly and never
    // commit to a bet — which would defeat the Jeopardy-final tension.
    var _wagerGate = { active: false, submitted: false };

    // Issue #183: render the question image banner + wire tap-to-zoom.
    function renderQuestionImageBanner(imgUrl) {
        var media = document.getElementById('question-media');
        var img = document.getElementById('question-image');
        if (!media || !img) return;
        var safeImg = (typeof imgUrl === 'string' && /^https?:\/\//i.test(imgUrl)) ? imgUrl : '';
        img.onerror = function() {
            // Image failed → hide the banner, fall back to text-only.
            img.removeAttribute('src');
            media.hidden = true;
        };
        if (safeImg) {
            img.src = safeImg;
            media.hidden = false;
        } else {
            img.removeAttribute('src');
            media.hidden = true;
        }
    }

    // Wire the fullscreen zoom overlay once. The overlay shows the current
    // banner image at full size; closing returns to the game view.
    function _initImageZoom() {
        var zoomBtn = document.getElementById('question-image-zoom');
        var overlay = document.getElementById('image-zoom-overlay');
        var closeBtn = document.getElementById('image-zoom-close');
        var overlayImg = document.getElementById('image-zoom-img');
        var bannerImg = document.getElementById('question-image');
        if (!zoomBtn || !overlay || !overlayImg) return;

        function open() {
            if (bannerImg && bannerImg.getAttribute('src')) {
                overlayImg.src = bannerImg.getAttribute('src');
                overlayImg.alt = bannerImg.getAttribute('alt') || '';
                overlay.classList.remove('hidden');
            }
        }
        function close() {
            overlay.classList.add('hidden');
            overlayImg.removeAttribute('src');
        }
        zoomBtn.addEventListener('click', open);
        if (closeBtn) closeBtn.addEventListener('click', close);
        overlay.addEventListener('click', function(e) {
            if (e.target === overlay) close();
        });
        document.addEventListener('keydown', function(e) {
            if (e.key === 'Escape' && !overlay.classList.contains('hidden')) close();
        });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', _initImageZoom);
    } else {
        _initImageZoom();
    }

    function renderQuestion(data) {
        var questionText = document.getElementById('question-text');
        var questionCategory = document.getElementById('question-category');
        var answerButtons = document.getElementById('answer-buttons');

        if (questionText) questionText.textContent = data.question_text || '';
        if (questionCategory) questionCategory.textContent = data.category || '';

        // Issue #25 + #183 (Variant 1): question image as a fixed-height
        // banner preview with tap-to-zoom. Only absolute http(s) URLs are
        // shown (server already sanitises; this is defence-in-depth).
        // Absent/invalid/load-error → the banner is hidden so the answer
        // pills stay reachable above the fold (graceful text-only fallback).
        renderQuestionImageBanner(data.image_url);

        // Wager round detection — set BEFORE we touch buttons so we can
        // disable them up-front, then enable once the wager is in.
        _wagerGate.active = !!data.is_final_round;
        _wagerGate.submitted = false;
        _renderWagerPanel(data.is_final_round, data.player_score || 0);

        if (answerButtons) {
            var answers = data.answers || [];
            var buttons = answerButtons.querySelectorAll('.answer-btn');

            for (var i = 0; i < buttons.length; i++) {
                var btn = buttons[i];
                btn.dataset.index = String(i);

                var textEl = btn.querySelector('.answer-text');
                if (textEl) textEl.textContent = answers[i] || '';

                // Re-apply selected state if player already submitted
                if (hasSubmitted && lastSubmittedIndex === i) {
                    btn.disabled = true;
                    btn.classList.add('is-selected');
                    btn.classList.remove('is-correct', 'is-wrong', 'is-eliminated', 'hidden');
                } else if (hasSubmitted) {
                    btn.disabled = true;
                    btn.classList.remove('is-selected', 'is-correct', 'is-wrong', 'is-eliminated', 'hidden');
                } else {
                    // Wager round: keep buttons disabled until wager submitted.
                    btn.disabled = _wagerGate.active && !_wagerGate.submitted;
                    btn.classList.remove('is-selected', 'is-correct', 'is-wrong', 'is-eliminated', 'hidden');
                }
            }
        }

        // Show/hide submitted confirmation
        var confirmation = document.getElementById('submitted-confirmation');
        if (confirmation) confirmation.classList.toggle('hidden', !hasSubmitted);
    }

    function _renderWagerPanel(isFinal, currentScore) {
        var panel = document.getElementById('wager-panel');
        if (!panel) return;

        var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };

        if (!isFinal) {
            panel.classList.add('hidden');
            return;
        }
        panel.classList.remove('hidden');

        var titleEl = document.getElementById('wager-panel-title');
        var hintEl = document.getElementById('wager-panel-hint');
        var slider = document.getElementById('wager-slider');
        var valueEl = document.getElementById('wager-value');
        var bankEl = document.getElementById('wager-bank');
        var submitBtn = document.getElementById('wager-submit-btn');

        if (titleEl) titleEl.textContent = t('wager.title');
        if (hintEl) hintEl.textContent = t('wager.hint');
        if (bankEl) bankEl.textContent = currentScore;
        if (slider) {
            slider.value = '25';  // sensible default — quarter of bank
            slider.disabled = false;
        }

        function syncValue() {
            var pct = parseInt(slider.value, 10);
            var pts = Math.floor(currentScore * pct / 100);
            if (valueEl) valueEl.textContent = pct + '% (' + pts + ' Pkt.)';
        }
        if (slider && valueEl) {
            slider.oninput = syncValue;
            syncValue();
        }

        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.textContent = t('wager.submit');
            submitBtn.onclick = function () {
                if (_wagerGate.submitted) return;
                _wagerGate.submitted = true;
                submitBtn.disabled = true;
                if (slider) slider.disabled = true;
                // Send via the player-core send() function.
                var send = window.QuizifyPlayer && window.QuizifyPlayer.send;
                if (send) send('submit_wager', { wager: parseInt(slider.value, 10) });
                // Unlock answer buttons.
                var answerButtons = document.getElementById('answer-buttons');
                if (answerButtons) {
                    answerButtons.querySelectorAll('.answer-btn').forEach(function (b) {
                        b.disabled = false;
                    });
                }
                // Collapse the panel into a smaller "wager: 25%" badge so
                // the player remembers what they bet during the question.
                panel.classList.add('wager-panel--collapsed');
                if (titleEl) titleEl.textContent = t('wager.locked', { pct: parseInt(slider.value, 10) });
                if (hintEl) hintEl.textContent = '';
            };
        }
    }

    // ============================================
    // Answer Submission
    // ============================================

    var hasSubmitted = false;
    var lastSubmittedIndex = -1;

    /**
     * Handle answer button click
     * @param {number} selectedIndex - Index of selected answer (0, 1, 2)
     * @param {Function} sendFn - Function to send WS messages
     */
    function handleAnswerClick(selectedIndex, sendFn) {
        if (hasSubmitted) return;
        hasSubmitted = true;
        lastSubmittedIndex = selectedIndex;

        var answerButtons = document.getElementById('answer-buttons');
        if (answerButtons) {
            var buttons = answerButtons.querySelectorAll('.answer-btn');
            for (var i = 0; i < buttons.length; i++) {
                buttons[i].disabled = true;
                if (parseInt(buttons[i].dataset.index, 10) === selectedIndex) {
                    buttons[i].classList.add('is-selected');
                }
            }
        }

        var confirmation = document.getElementById('submitted-confirmation');
        if (confirmation) confirmation.classList.remove('hidden');

        sendFn('submit_answer', { answer_index: selectedIndex });
    }

    /**
     * Reset submission state for new round
     */
    function getLastSubmittedIndex() {
        return lastSubmittedIndex;
    }

    /**
     * Lock the UI into the "already submitted" state.
     * Used when reconnecting mid-round (#14 in logical review): server says
     * we've already submitted, so disable all answer buttons and show the
     * confirmation, even though we don't know which answer index we picked.
     */
    function lockSubmitted() {
        hasSubmitted = true;
        var answerButtons = document.getElementById('answer-buttons');
        if (answerButtons) {
            var buttons = answerButtons.querySelectorAll('.answer-btn');
            for (var i = 0; i < buttons.length; i++) {
                buttons[i].disabled = true;
            }
        }
        var confirmation = document.getElementById('submitted-confirmation');
        if (confirmation) confirmation.classList.remove('hidden');
    }

    function resetSubmissionState() {
        hasSubmitted = false;
        lastSubmittedIndex = -1;

        var answerButtons = document.getElementById('answer-buttons');
        if (answerButtons) {
            var buttons = answerButtons.querySelectorAll('.answer-btn');
            for (var i = 0; i < buttons.length; i++) {
                buttons[i].disabled = false;
                buttons[i].classList.remove('is-selected', 'is-correct', 'is-wrong', 'is-eliminated', 'correct', 'wrong', 'dimmed');
            }
        }

        var confirmation = document.getElementById('submitted-confirmation');
        if (confirmation) confirmation.classList.add('hidden');
    }

    // ============================================
    // Game View Update
    // ============================================

    /**
     * Update game view with round data
     * @param {Object} data - State data from server
     */
    function updateGameView(data) {
        var currentRound = document.getElementById('current-round');
        var totalRounds = document.getElementById('total-rounds');
        var lastRoundBanner = document.getElementById('last-round-banner');

        if (currentRound) currentRound.textContent = data.round || 1;
        if (totalRounds) totalRounds.textContent = data.total_rounds || 10;

        if (lastRoundBanner) {
            if (data.last_round) {
                lastRoundBanner.classList.remove('hidden');
            } else {
                lastRoundBanner.classList.add('hidden');
            }
        }

        renderSubmissionTracker(data.players);

        if (data.leaderboard) {
            updateLeaderboard(data, 'leaderboard-list');
        } else if (data.players && data.players.length > 0) {
            // Fallback for round 1: server doesn't send `leaderboard` until
            // the round-summary message, so during the very first question
            // the section sat empty ("--"). Derive a zero-score board from
            // the player list so users see who they're up against.
            var fallback = data.players.map(function (p, idx) {
                return {
                    name: p.name,
                    score: p.score || 0,
                    rank: idx + 1,
                    color: p.color,
                    is_current: p.name === state.playerName,
                    connected: p.connected !== false,
                    streak: 0,
                };
            });
            updateLeaderboard({ leaderboard: fallback }, 'leaderboard-list');
        }
    }

    // ============================================
    // Submission Tracker
    // ============================================

    /**
     * Get initials from player name
     * @param {string} name - Player name
     * @returns {string} Initials (1-2 characters)
     */
    function getInitials(name) {
        if (!name) return '?';
        var trimmed = name.trim();
        if (!trimmed) return '?';

        var parts = trimmed.split(/[\s-]+/).filter(Boolean);
        if (parts.length >= 2) {
            return (parts[0][0] + parts[1][0]).toUpperCase();
        }
        return trimmed.slice(0, Math.min(2, trimmed.length)).toUpperCase();
    }

    /**
     * Render submission tracker showing who has submitted
     * @param {Array} players - Array of player objects
     */
    // Latest player list from the server, cached so the freeze/steal target
    // picker can render opponents without re-requesting state.
    var _latestPlayers = [];

    function renderSubmissionTracker(players) {
        var tracker = document.getElementById('submission-tracker');
        var container = document.getElementById('submitted-players');

        var playerList = players || [];
        _latestPlayers = playerList;

        if (!tracker || !container) return;
        var submittedCount = playerList.filter(function (p) {
            return p.submitted;
        }).length;
        var totalCount = playerList.length;

        var allSubmitted = submittedCount === totalCount && totalCount > 0;
        tracker.classList.toggle('all-submitted', allSubmitted);

        container.innerHTML = playerList.map(function (player) {
            var initials = getInitials(player.name);
            var isCurrentPlayer = player.name === state.playerName;
            var isDisconnected = player.connected === false;
            var classes = [
                'player-indicator',
                player.submitted ? 'is-submitted' : '',
                isCurrentPlayer ? 'is-current-player' : '',
                isDisconnected ? 'player-indicator--disconnected' : ''
            ].filter(Boolean).join(' ');

            return '<div class="' + classes + '">' +
                '<div class="player-avatar">' +
                    '<span class="player-initials">' + pu.escapeHtml(initials) + '</span>' +
                '</div>' +
                '<span class="player-name">' + pu.escapeHtml(player.name) + '</span>' +
            '</div>';
        }).join('');
    }

    // ============================================
    // Leaderboard
    // ============================================

    /**
     * Update leaderboard display
     * @param {Object} data - State data containing leaderboard
     * @param {string} targetListId - ID of list container
     */
    var _prevLeaderboardRanks = {}; // name -> rank

    function updateLeaderboard(data, targetListId) {
        var leaderboard = data.leaderboard || [];
        var listEl = document.getElementById(targetListId || 'leaderboard-list');
        if (!listEl) return;

        leaderboard.forEach(function (entry) {
            entry.is_current = (entry.name === state.playerName);
            // Calculate rank delta vs previous
            var prevRank = _prevLeaderboardRanks[entry.name];
            if (prevRank !== undefined && prevRank !== entry.rank) {
                entry.rank_delta = prevRank - entry.rank; // positive = moved up
            } else {
                entry.rank_delta = 0;
            }
        });

        var displayList = compressLeaderboard(leaderboard, state.playerName);

        // FLIP animation: record old positions before DOM update
        var oldPositions = {};
        listEl.querySelectorAll('.leaderboard-entry[data-name]').forEach(function(el) {
            oldPositions[el.dataset.name] = el.getBoundingClientRect().top;
        });

        var html = '';
        displayList.forEach(function (entry) {
            html += renderLeaderboardEntry(entry);
        });

        listEl.innerHTML = html;

        // FLIP: animate from old positions to new
        var prefersReduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        if (!prefersReduced && Object.keys(oldPositions).length > 0) {
            listEl.querySelectorAll('.leaderboard-entry[data-name]').forEach(function(el) {
                var name = el.dataset.name;
                if (oldPositions[name] !== undefined) {
                    var newTop = el.getBoundingClientRect().top;
                    var delta = oldPositions[name] - newTop;
                    if (Math.abs(delta) > 2) {
                        el.style.transform = 'translateY(' + delta + 'px)';
                        el.style.transition = 'none';
                        requestAnimationFrame(function() {
                            el.style.transition = 'transform 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
                            el.style.transform = '';
                        });
                    }
                }
            });
        }

        // Store current ranks for next update
        leaderboard.forEach(function(entry) {
            _prevLeaderboardRanks[entry.name] = entry.rank;
        });

        if (leaderboard.length > 8) {
            scrollToCurrentPlayer(listEl);
        }

        updateLeaderboardSummary(leaderboard);
    }

    /**
     * Compress leaderboard for display when >10 players
     */
    function compressLeaderboard(players, currentPlayerName) {
        if (players.length <= 10) return players;

        var top5 = players.slice(0, 5);
        var bottom3 = players.slice(-3);
        var currentIdx = -1;

        for (var i = 0; i < players.length; i++) {
            if (players[i].name === currentPlayerName) {
                currentIdx = i;
                break;
            }
        }

        if (currentIdx < 5 || currentIdx >= players.length - 3) {
            return [].concat(top5, [{ separator: true }], bottom3);
        }

        return [].concat(
            top5,
            [{ separator: true }],
            [players[currentIdx]],
            [{ separator: true }],
            bottom3
        );
    }

    /**
     * Render a single leaderboard entry
     */
    function renderLeaderboardEntry(entry) {
        if (entry.separator) {
            return '<div class="leaderboard-separator">...</div>';
        }

        var rank = entry.rank || 0;
        var rankClass = rank <= 3 ? ' rank-' + rank : '';
        var currentClass = entry.is_current ? ' is-current' : '';
        var disconnectedClass = entry.connected === false ? ' is-disconnected' : '';
        var youBadge = entry.is_current ? '<span class="you-badge">(you)</span>' : '';
        var streakBadge = entry.streak > 1
            ? '<span class="leaderboard-streak">' + entry.streak + 'x</span>'
            : '';
        var deltaBadge = '';
        if (entry.rank_delta > 0) {
            deltaBadge = '<span class="rank-delta rank-delta--up">▲' + entry.rank_delta + '</span>';
        } else if (entry.rank_delta < 0) {
            deltaBadge = '<span class="rank-delta rank-delta--down">▼' + Math.abs(entry.rank_delta) + '</span>';
        }

        var colorDot = entry.color
            ? '<span class="player-color-dot" style="background:' + entry.color + '"></span>'
            : '';
        var colorBorder = entry.color ? ' style="border-left:3px solid ' + entry.color + '"' : '';
        return '<div class="leaderboard-entry' + currentClass + disconnectedClass + '"' + colorBorder + ' data-name="' + pu.escapeHtml(entry.name) + '">' +
            '<span class="entry-rank' + rankClass + '">' + rank + '</span>' +
            colorDot +
            '<span class="entry-name">' + pu.escapeHtml(entry.name) + youBadge + '</span>' +
            deltaBadge +
            '<span class="entry-score">' + entry.score + '</span>' +
            streakBadge +
        '</div>';
    }

    /**
     * Scroll leaderboard to show current player
     */
    function scrollToCurrentPlayer(listEl) {
        var currentEntry = listEl.querySelector('.leaderboard-entry.is-current');
        if (currentEntry) {
            currentEntry.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
    }

    /**
     * Update leaderboard summary badge.
     *
     * Shows the leader plus a "+N more" hint so a player below 1st place
     * knows the list expands. Without the hint, the collapsed summary
     * just reads "Alice: 19" and players 2-N have no signal that the
     * full board exists. Singular vs plural matters in German ("1
     * weiterer" / "2 weitere").
     */
    function updateLeaderboardSummary(leaderboard) {
        var summaryIds = ['leaderboard-summary', 'reveal-leaderboard-summary'];
        var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };

        summaryIds.forEach(function (id) {
            var summaryEl = document.getElementById(id);
            if (!summaryEl || !leaderboard || leaderboard.length === 0) return;

            var leader = leaderboard[0];
            if (!leader) return;

            var summary = leader.name + ': ' + leader.score;
            var others = leaderboard.length - 1;
            if (others === 1) {
                summary += '  ' + t('lobby.andOthersOne');
            } else if (others > 1) {
                summary += '  ' + t('lobby.andOthers', { count: others });
            }
            summaryEl.textContent = summary;
        });
    }

    // ============================================
    // Power-up
    // ============================================

    /**
     * Handle power-up button visibility
     * @param {string|null} powerupType - Power-up type or null
     */
    var POWERUP_LABELS = {
        joker: '🃏 Joker',
        double_points: '✨ Double',
        freeze: '🧊 Freeze',
        time_boost: '⏰ +5s',
        steal: '🥷 Steal',
    };

    function renderPowerUp(powerupType) {
        var powerupBtn = document.getElementById('powerup-btn');
        if (!powerupBtn) return;

        if (powerupType) {
            powerupBtn.classList.remove('hidden', 'used');
            var label = powerupBtn.querySelector('.powerup-label') || powerupBtn;
            label.textContent = POWERUP_LABELS[powerupType] || powerupType;
        } else {
            powerupBtn.classList.add('hidden');
        }
    }

    /**
     * Returns true for power-up types whose effect lands on another player
     * (and therefore need a target picker).
     */
    function powerupNeedsTarget(powerupType) {
        return powerupType === 'freeze' || powerupType === 'steal';
    }

    /**
     * Open the target-picker modal so the player can choose who to freeze
     * or steal from. Calls onConfirm(targetPlayerName) on selection.
     */
    function openTargetPicker(powerupType, onConfirm) {
        var modal = document.getElementById('powerup-target-modal');
        var titleEl = document.getElementById('powerup-target-title');
        var hintEl = document.getElementById('powerup-target-hint');
        var listEl = document.getElementById('powerup-target-list');
        var cancelBtn = document.getElementById('powerup-target-cancel');
        if (!modal || !listEl) return;

        var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };

        // Active opponents = connected, not the local player.
        var me = pu.state.playerName;
        var opponents = (_latestPlayers || []).filter(function (p) {
            return p && p.name && p.name !== me && p.connected !== false;
        });

        if (titleEl) {
            titleEl.textContent = powerupType === 'steal'
                ? t('powerups.pickStealTitle')
                : t('powerups.pickFreezeTitle');
        }

        listEl.innerHTML = '';

        if (opponents.length === 0) {
            if (hintEl) hintEl.textContent = t('powerups.noOpponents');
        } else {
            // STEAL is most effective after the target has locked in their
            // answer (target.round_score is non-zero, so half is non-zero).
            // Surface that as a hint + per-opponent "answered" badge so
            // players don't burn the power-up on someone who hasn't yet
            // earned anything to steal. FREEZE keeps the generic pickHint
            // (server v1.1.25 rejects submitted targets for FREEZE anyway).
            if (hintEl) {
                hintEl.textContent = powerupType === 'steal'
                    ? t('powerups.stealHint')
                    : t('powerups.pickHint');
            }
            opponents.forEach(function (opp) {
                var li = document.createElement('li');
                var btn = document.createElement('button');
                btn.type = 'button';
                btn.className = 'powerup-target-option';
                btn.dataset.player = opp.name;
                var colorDot = '';
                if (opp.color) {
                    colorDot = '<span class="powerup-target-dot" style="background:' +
                        pu.escapeHtml(opp.color) + '"></span>';
                }
                var submittedBadge = '';
                if (powerupType === 'steal' && opp.submitted) {
                    submittedBadge = '<span class="powerup-target-submitted">' +
                        pu.escapeHtml(t('powerups.targetAnswered')) + '</span>';
                }
                btn.innerHTML = colorDot +
                    '<span class="powerup-target-name">' + pu.escapeHtml(opp.name) + '</span>' +
                    submittedBadge;
                btn.addEventListener('click', function () {
                    closeTargetPicker();
                    onConfirm(opp.name);
                });
                li.appendChild(btn);
                listEl.appendChild(li);
            });
        }

        modal.classList.remove('hidden');

        // One-shot listeners; closeTargetPicker tears them down.
        function onCancel() { closeTargetPicker(); }
        function onBackdrop(e) {
            if (e.target && e.target.classList.contains('powerup-target-backdrop')) {
                closeTargetPicker();
            }
        }
        function onKey(e) {
            if (e.key === 'Escape') closeTargetPicker();
        }
        if (cancelBtn) cancelBtn.addEventListener('click', onCancel, { once: true });
        modal.addEventListener('click', onBackdrop);
        document.addEventListener('keydown', onKey);
        modal._teardown = function () {
            modal.removeEventListener('click', onBackdrop);
            document.removeEventListener('keydown', onKey);
            if (cancelBtn) cancelBtn.removeEventListener('click', onCancel);
        };
    }

    function closeTargetPicker() {
        var modal = document.getElementById('powerup-target-modal');
        if (!modal) return;
        modal.classList.add('hidden');
        if (typeof modal._teardown === 'function') {
            modal._teardown();
            modal._teardown = null;
        }
    }

    /**
     * Handle joker power-up applied - eliminate one wrong answer
     * @param {number} removeIndex - Index of answer to eliminate
     */
    function applyJoker(removeIndex) {
        var answerButtons = document.getElementById('answer-buttons');
        if (!answerButtons) return;

        var buttons = answerButtons.querySelectorAll('.answer-btn');
        for (var i = 0; i < buttons.length; i++) {
            if (parseInt(buttons[i].dataset.index, 10) === removeIndex) {
                buttons[i].classList.add('is-eliminated');
                buttons[i].disabled = true;
                break;
            }
        }
    }

    // ============================================
    // Answer Result Storage
    // ============================================

    var lastAnswerResult = null;

    /**
     * Store answer result for reveal phase
     * @param {Object} data - Answer result data
     */
    function handleAnswerResult(data) {
        lastAnswerResult = data;
    }

    /**
     * Get stored answer result
     */
    function getLastAnswerResult() {
        return lastAnswerResult;
    }

    /**
     * Clear stored answer result
     */
    function clearLastAnswerResult() {
        lastAnswerResult = null;
    }

    // ============================================
    // Export
    // ============================================

    window.QuizifyPlayerGame = {
        startCountdown: startCountdown,
        stopCountdown: stopCountdown,
        updateTimer: updateTimer,
        renderQuestion: renderQuestion,
        handleAnswerClick: handleAnswerClick,
        lockSubmitted: lockSubmitted,
        resetSubmissionState: resetSubmissionState,
        updateGameView: updateGameView,
        renderSubmissionTracker: renderSubmissionTracker,
        updateLeaderboard: updateLeaderboard,
        renderLeaderboardEntry: renderLeaderboardEntry,
        updateLeaderboardSummary: updateLeaderboardSummary,
        renderPowerUp: renderPowerUp,
        powerupNeedsTarget: powerupNeedsTarget,
        openTargetPicker: openTargetPicker,
        closeTargetPicker: closeTargetPicker,
        applyJoker: applyJoker,
        handleAnswerResult: handleAnswerResult,
        getLastAnswerResult: getLastAnswerResult,
        clearLastAnswerResult: clearLastAnswerResult,
        getLastSubmittedIndex: getLastSubmittedIndex
    };

})();


/* ============ player-core.js ============ */

/**
 * Quizify Player - Core Module (Entry Point)
 * WebSocket connection, session management, state routing, reconnect logic
 */

(function () {
    'use strict';

    var pu = window.QuizifyPlayerUtils;
    var lobby = window.QuizifyPlayerLobby;
    var game = window.QuizifyPlayerGame;
    var reveal = window.QuizifyPlayerReveal;
    var end = window.QuizifyPlayerEnd;
    var lightning = window.QuizifyPlayerLightning;
    var state = pu.state;

    // ============================================
    // DOM Refs
    // ============================================

    var els = {
        nameInput: document.getElementById('name-input'),
        joinBtn: document.getElementById('join-btn')
    };

    // ============================================
    // Local State
    // ============================================

    var currentQuestion = null;
    var myPowerUp = null;

    // ============================================
    // Send Helper
    // ============================================

    function send(type, payload) {
        if (state.ws && state.ws.readyState === WebSocket.OPEN) {
            state.ws.send(JSON.stringify(Object.assign({ type: type }, payload || {})));
        }
    }

    // ============================================
    // Connect WebSocket
    // ============================================

    var _wsOpenTimeout = null;

    function connect() {
        state.ws = pu.createWebSocket('/api/quizify/ws', {
            onOpen: function () {
                // Clear the connection timeout
                if (_wsOpenTimeout) { clearTimeout(_wsOpenTimeout); _wsOpenTimeout = null; }

                // Re-enable join button once WS is open. Compare via i18n
                // so a German player whose button reads "Erneut verbinden"
                // also gets flipped back to "Beitreten".
                if (els.joinBtn && !state.playerName) {
                    var tConn = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
                    var nameVal = els.nameInput ? els.nameInput.value.trim() : '';
                    els.joinBtn.disabled = nameVal.length === 0;
                    if (els.joinBtn.textContent === tConn('connection.retryConnection')) {
                        els.joinBtn.textContent = tConn('join.joinButton');
                    }
                }

                // Try session-based reconnect first — but skip for admin
                // self-join (?admin=true) to avoid a stale session token
                // from a prior game blocking the fresh join. The exception
                // is `?reconnect=1`, which the admin lobby sets when it
                // redirects after joining-as-player on the admin WS: the
                // token in sessionStorage was JUST written, so we trust it
                // and reconnect instead of doing a fresh join (which would
                // race against the still-open admin WS and fail with
                // "Name bereits vergeben").
                var session = pu.getSession();
                var params = new URLSearchParams(location.search);
                var isAdminSelfJoin = params.get('admin') === 'true';
                var forceReconnect = params.get('reconnect') === '1';
                var useReconnect = (!isAdminSelfJoin || forceReconnect) && session.token && session.name;
                if (useReconnect) {
                    send('reconnect', { session_token: session.token, name: session.name });
                } else if (state.playerName) {
                    var joinMsg = { name: state.playerName };
                    // Admin self-join: send `is_admin: true` in the join
                    // message. Server trusts the flag (Beatify pattern).
                    // No more cryptographic token threading through join
                    // — the persisted admin token is only validated for
                    // the pure admin-dashboard WS connect, not for player
                    // joins. See DESIGN.md for the trust model.
                    if (isAdminSelfJoin) {
                        state.isAdmin = true;
                    }
                    if (state.isAdmin) joinMsg.is_admin = true;
                    send('join', joinMsg);
                }
                // else: waiting for auto-join interval or user to click join
            },
            onMessage: handleMessage,
            onReconnect: connect,
            onClose: function () {
                state.ws = null;
            }
        });
    }

    // ============================================
    // Document title — reflects current phase so users with multiple
    // tabs open can tell which one is active. Was previously stuck on
    // "Quizify - Join Game" forever.
    // ============================================

    // Snapshot of the most-recent phase/msg so updatePageTitle can fire
    // again once i18n finishes loading. Without this, an admin-self-join
    // redirect that lands while game_state is already QUESTION_ACTIVE
    // would lose its title-update call (i18n.isReady() was still false
    // at that moment) and the tab title stuck on "Quizify — Beitreten"
    // for the entire round.
    var _lastTitlePhase = null;
    var _lastTitleMsg = null;

    // ============================================
    // Screen Wake Lock
    // Phones lock the screen mid-question if the player isn't tapping —
    // by the time they look up the next question is on. Hold a wake
    // lock during QUESTION_ACTIVE only (don't drain battery in lobby
    // or reveal). The lock auto-releases when the tab goes hidden;
    // we re-acquire on visibilitychange below.
    // ============================================
    var _wakeLock = null;

    async function _acquireWakeLock() {
        if (!('wakeLock' in navigator)) return;  // unsupported browser
        if (_wakeLock) return;  // already held
        try {
            _wakeLock = await navigator.wakeLock.request('screen');
            _wakeLock.addEventListener('release', function () {
                // OS released it (tab hidden, low battery, etc.) —
                // clear so visibilitychange handler will re-acquire.
                _wakeLock = null;
            });
        } catch (e) {
            // NotAllowedError on iframes/permissions — silent.
            _wakeLock = null;
        }
    }

    function _releaseWakeLock() {
        if (_wakeLock) {
            try { _wakeLock.release(); } catch (e) { /* ignore */ }
            _wakeLock = null;
        }
    }

    function updatePageTitle(phase, msg) {
        _lastTitlePhase = phase;
        _lastTitleMsg = msg;
        if (!window.QuizifyI18n || !window.QuizifyI18n.isReady()) return;
        var t = window.QuizifyI18n.t;
        var title;
        switch (phase) {
            case 'LOBBY':
                title = state.playerName ? t('page.titleLobby') : t('page.titleJoin');
                break;
            case 'QUESTION_ACTIVE':
            case 'PLAYING':
                title = t('page.titleQuestion', { current: (msg && msg.round) || 1 });
                break;
            case 'ANSWER_REVEAL':
            case 'REVEAL':
                title = t('page.titleReveal');
                break;
            case 'FINALE':
            case 'END':
                title = t('page.titleFinale');
                break;
            default:
                title = t('page.titleJoin');
        }
        if (title && title !== document.title) document.title = title;
    }

    // Re-fire any pending title update once i18n has finished loading.
    function _flushPendingTitle() {
        if (_lastTitlePhase) updatePageTitle(_lastTitlePhase, _lastTitleMsg);
    }

    // ============================================
    // Message Router
    // ============================================

    function handleMessage(msg) {
        switch (msg.type || msg.event) {
            case 'game_state':
                handleGameState(msg);
                break;

            case 'game_reset':
                // Admin wiped the whole session (issue #207). Drop our
                // identity + session token so the now-stale token can't
                // resurrect us, and return to the join screen explicitly.
                // The server also closes our socket right after this, but
                // handling the broadcast directly makes the return to the
                // join screen deterministic instead of relying on the
                // close + reconnect_failed race.
                pu.clearSession();
                state.sessionToken = null;
                state.playerName = null;
                state.playerId = null;
                state.isAdmin = false;
                pu.showView('join-view');
                break;

            case 'joined':
            case 'reconnected':
                state.playerName = msg.player_id || state.playerName;
                state.playerId = msg.player_id;
                if (msg.session_token) {
                    state.sessionToken = msg.session_token;
                    pu.saveSession(msg.session_token, state.playerName);
                }
                if (msg.is_admin) state.isAdmin = true;
                if (msg.color) {
                    state.playerColor = msg.color;
                    // Apply as CSS custom property on root for global use
                    document.documentElement.style.setProperty('--my-player-color', msg.color);
                }
                // Request full state so we switch to the correct view immediately
                send('get_state', {});
                break;

            case 'reconnect_failed':
                // The stored session token no longer maps to a joinable game
                // (game ended/reset, or token expired). Drop the stale token
                // and route back to the join screen — without this the client
                // is left with every view hidden → blank screen (issue #227,
                // same family as #207/#221). Mirror the deterministic return
                // used by game_reset above.
                pu.clearSession();
                state.sessionToken = null;
                pu.showView('join-view');
                break;

            case 'player_joined':
                lobby.handlePlayerJoined(msg);
                break;

            case 'player_left':
                lobby.handlePlayerLeft(msg);
                break;

            case 'question_started':
                // On the final round, play a brief dramatic flourish + 3·2·1
                // countdown on the big screen BEFORE revealing the question.
                // Pure tension/UX — works regardless of finale type. If timing
                // data is missing or anything goes wrong, we reveal instantly.
                if (isFinalRound(msg)) {
                    playFinaleCountdown(function () { handleQuestionStarted(msg); });
                } else {
                    handleQuestionStarted(msg);
                }
                break;

            case 'timer_tick':
                game.updateTimer(msg.remaining);
                break;

            case 'answer_result':
                game.handleAnswerResult(msg);
                // Streak milestone toast
                if (msg.correct && msg.new_streak) {
                    var streakKeys = { 3: 'game.streakToast3', 5: 'game.streakToast5', 7: 'game.streakToast7' };
                    if (streakKeys[msg.new_streak]) {
                        pu.showToast(t(streakKeys[msg.new_streak]), 2500);
                    }
                }
                break;

            case 'round_summary':
                handleRoundSummary(msg);
                break;

            case 'finale':
                handleFinale(msg);
                break;

            case 'powerup_assigned':
                myPowerUp = msg.powerup_type;
                break;

            case 'powerup_applied':
                handlePowerUpApplied(msg);
                break;

            case 'rematch_started':
                state.reconnectAttempts = 0;
                connect();
                break;

            case 'reaction':
                showFloatingReaction(msg.emoji, msg.player_name);
                break;

            case 'reaction_bonus':
                // Server awarded +1 to one or more correct answerers
                // (gameplay idea #11). If I'm one of the recipients,
                // flash a "+1 from X 🎉" toast. Either way the
                // leaderboard payload updates scores.
                handleReactionBonus(msg);
                break;

            case 'wager_accepted':
                // Server confirmed our final-round wager. Nothing to
                // do — the local UI already collapsed the panel on
                // submit. Useful as a hook for analytics later.
                break;

            // ---- Lightning Round (issue #42) ----
            case 'lightning_splash':
                if (lightning) lightning.handleLightningSplash(msg);
                break;

            case 'lightning_question':
                if (lightning) lightning.handleLightningQuestion(msg);
                break;
            case 'lightning_tick':
                if (lightning) lightning.handleLightningTick(msg);
                break;
            case 'lightning_answer_result':
                if (lightning) lightning.handleLightningAnswerResult(msg);
                break;
            case 'lightning_recap':
                if (lightning) lightning.handleLightningRecap(msg);
                break;

            case 'error':
                handleError(msg);
                break;
        }
    }

    function handleReactionBonus(msg) {
        var to = msg.to_players || [];
        var from = msg.from_player || '';
        if (state.playerName && to.indexOf(state.playerName) !== -1 && from) {
            var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
            var toast = document.createElement('div');
            toast.className = 'reaction-bonus-toast';
            toast.textContent = t('wager.bonusFromReaction', { from: from });
            document.body.appendChild(toast);
            setTimeout(function () { toast.remove(); }, 1600);
        }
        // If the server included an updated leaderboard, refresh it.
        if (msg.leaderboard && game && game.updateLeaderboard) {
            game.updateLeaderboard({ leaderboard: msg.leaderboard }, 'reveal-leaderboard-list');
        }
    }

    // ============================================
    // Game State Handler
    // ============================================

    function handleGameState(msg) {
        state.currentPhase = msg.phase;

        // Keep the in-game leaderboard panel current from ANY game_state that
        // carries a leaderboard (the round-start refresh and the ANSWER_REVEAL
        // broadcast both do). Without this the panel was never fed during a
        // live question — only the reveal's own `reveal-leaderboard-list` was —
        // so #leaderboard-list/#leaderboard-summary sat at "--" mid-round (#235).
        if (msg.leaderboard && game && game.updateLeaderboard) {
            game.updateLeaderboard({ leaderboard: msg.leaderboard }, 'leaderboard-list');
        }

        // Wake lock: only hold during active question. Cheap battery,
        // doesn't fight the OS on lobby/reveal/finale screens where
        // a sleeping screen costs nothing.
        if (msg.phase === 'QUESTION_ACTIVE' || msg.phase === 'PLAYING') {
            _acquireWakeLock();
        } else {
            _releaseWakeLock();
            // Drop any in-flight finale flourish when leaving an active round
            // (pause / reveal / reset / reconnect into a non-question phase).
            _clearFinaleCountdown();
        }

        // Sync UI language with the server-side game language so a
        // German game shows German labels even if the player's
        // browser is English. Only triggers a reload of translations
        // when the language actually changes.
        if (msg.language && window.QuizifyI18n &&
            window.QuizifyI18n.getLanguage() !== msg.language) {
            window.QuizifyI18n.setLanguage(msg.language).then(function () {
                window.QuizifyI18n.initPageTranslations();
                updatePageTitle(msg.phase, msg);
            });
        } else {
            updatePageTitle(msg.phase, msg);
        }

        if (msg.players) lobby.handlePlayerJoined(msg);

        switch (msg.phase) {
            case 'LOBBY':
                if (!state.playerName) {
                    pu.showView('join-view');
                } else {
                    pu.showView('lobby-view');
                    lobby.renderLobby(msg);
                }
                break;

            case 'QUESTION_ACTIVE':
            case 'PLAYING':
                if (msg.question) {
                    handleQuestionStarted({
                        question_text: msg.question.text,
                        answers: msg.question.answers,
                        // Use time_remaining for mid-round joiners, fall back to time_limit
                        timer_duration: msg.question.time_remaining || msg.question.time_limit,
                        round_num: msg.round,
                        total_rounds: msg.total_rounds,
                        category: msg.question.category
                    });

                    // #14: if we're reconnecting mid-round and server thinks
                    // we've already submitted, lock the UI accordingly so we
                    // don't get ERR_ALREADY_SUBMITTED toasts on re-tap.
                    if (msg.leaderboard && state.playerName) {
                        var me = msg.leaderboard.find(function (p) {
                            return p && p.name === state.playerName;
                        });
                        if (me && me.submitted) {
                            game.lockSubmitted();
                        }
                    }
                } else {
                    pu.showView('game-view');
                }
                break;

            case 'ANSWER_REVEAL':
            case 'REVEAL':
                pu.showView('reveal-view');
                reveal.updateRevealView(msg);
                break;

            case 'FINALE':
            case 'END':
                handleFinale(msg);
                break;

            case 'LIGHTNING':
                // Reconnect / fresh snapshot landing into a live lightning
                // round. Server pushes per-question lightning_question events
                // for the live flow; this just gets us onto the right view
                // with the current question if present.
                if (lightning && msg.lightning && msg.lightning.splash_pending) {
                    // Round armed but the intro splash (#201) is still up.
                    lightning.handleLightningSplash({
                        num_questions: msg.lightning.num_questions,
                        seconds_per_question: msg.lightning.seconds_per_question
                    });
                } else if (lightning && msg.lightning) {
                    var lq = msg.lightning.question;
                    lightning.handleLightningQuestion({
                        question_text: lq ? lq.text : '',
                        answers: lq ? lq.answers : [],
                        index: msg.lightning.index,
                        num_questions: msg.lightning.num_questions,
                        seconds: msg.lightning.time_remaining,
                        category: lq ? lq.category : '',
                        image_url: lq ? lq.image_url : ''
                    });
                } else {
                    pu.showView('lightning-view');
                }
                break;

            case 'LIGHTNING_RECAP':
                if (lightning) lightning.handleLightningRecap({ recap: msg.lightning_recap });
                break;

            case 'PAUSED':
                pu.showView('paused-view');
                updatePausedView(msg);
                // Admin's control bar stays visible during pause so they
                // can resume / end. Swap Pause ↔ Resume.
                var adminBarP = document.getElementById('admin-control-bar');
                if (adminBarP) adminBarP.classList.toggle('hidden', !state.isAdmin);
                var pauseBtnP = document.getElementById('pause-game-btn');
                var resumeBtnP = document.getElementById('resume-game-btn');
                if (pauseBtnP) pauseBtnP.classList.add('hidden');
                if (resumeBtnP) resumeBtnP.classList.remove('hidden');
                break;

            default:
                // Safety net (issue #227, same reasoning as #221): an unknown
                // or unmapped phase must never leave the player with zero
                // visible views (blank screen). Fall back to the lobby if we
                // already have an identity, otherwise the join screen.
                pu.showView(state.playerName ? 'lobby-view' : 'join-view');
                break;
        }
    }

    // ============================================
    // Question Started
    // ============================================

    // ============================================
    // Finale Countdown (dramatic flourish before the final question)
    // ============================================

    var _finaleCountdownTimers = [];

    // True when this question_started marks the last round. Prefer the
    // explicit server flag; fall back to round_num >= total_rounds so the
    // countdown still fires even if is_final_round is ever absent.
    function isFinalRound(msg) {
        if (!msg) return false;
        if (msg.is_final_round === true) return true;
        var rn = msg.round_num;
        var tr = msg.total_rounds;
        return typeof rn === 'number' && typeof tr === 'number' && tr > 0 && rn >= tr;
    }

    function _clearFinaleCountdown() {
        for (var i = 0; i < _finaleCountdownTimers.length; i++) {
            clearTimeout(_finaleCountdownTimers[i]);
        }
        _finaleCountdownTimers = [];
        var overlay = document.getElementById('finale-countdown-overlay');
        if (overlay) {
            overlay.classList.add('hidden');
            overlay.setAttribute('aria-hidden', 'true');
        }
    }

    // Show "Finale!" then 3 · 2 · 1 (~2.4s total), then run `done`. The reveal
    // is always invoked exactly once, even if something throws — the final
    // question must never be swallowed by this purely cosmetic flourish.
    function playFinaleCountdown(done) {
        var fired = false;
        function finish() {
            if (fired) return;
            fired = true;
            _clearFinaleCountdown();
            try { done(); } catch (e) { /* reveal already in progress */ }
        }

        var overlay = document.getElementById('finale-countdown-overlay');
        var numberEl = document.getElementById('finale-countdown-number');
        if (!overlay || !numberEl) {
            // No overlay element (older cached HTML) — skip straight to reveal.
            finish();
            return;
        }

        try {
            _clearFinaleCountdown();
            numberEl.textContent = '';
            overlay.classList.remove('hidden');
            overlay.setAttribute('aria-hidden', 'false');

            // Flourish shows alone for ~0.7s, then 3 · 2 · 1 at 0.6s each.
            var digits = [3, 2, 1];
            digits.forEach(function (d, idx) {
                _finaleCountdownTimers.push(setTimeout(function () {
                    numberEl.textContent = String(d);
                    // Re-trigger the pop animation by toggling the class.
                    numberEl.classList.remove('tick');
                    // Force reflow so the animation restarts on each digit.
                    void numberEl.offsetWidth;
                    numberEl.classList.add('tick');
                }, 700 + idx * 600));
            });

            // After the last digit finishes, reveal the question.
            _finaleCountdownTimers.push(setTimeout(finish, 700 + digits.length * 600));
        } catch (e) {
            finish();
        }
    }

    function handleQuestionStarted(msg) {
        state.currentPhase = 'QUESTION_ACTIVE';
        currentQuestion = msg;

        pu.showView('game-view');

        // Render question and answers
        game.renderQuestion(msg);
        game.resetSubmissionState();

        // Round indicator
        var currentRound = document.getElementById('current-round');
        var totalRounds = document.getElementById('total-rounds');
        if (currentRound) currentRound.textContent = msg.round_num || 1;
        if (totalRounds) totalRounds.textContent = msg.total_rounds || 10;

        // Timer
        if (msg.timer_duration) {
            var deadline = Date.now() + (msg.timer_duration * 1000);
            game.startCountdown(deadline);
        }

        // Power-up
        game.renderPowerUp(myPowerUp);

        // Admin control bar during QUESTION_ACTIVE: End + Pause (no Next)
        var adminBar = document.getElementById('admin-control-bar');
        if (adminBar) {
            adminBar.classList.toggle('hidden', !state.isAdmin);
        }
        var nextRoundAdminBtn = document.getElementById('next-round-admin-btn');
        var skipBtn = document.getElementById('skip-question-btn');
        var pauseBtn = document.getElementById('pause-game-btn');
        var resumeBtn = document.getElementById('resume-game-btn');
        if (nextRoundAdminBtn) nextRoundAdminBtn.classList.add('hidden');
        if (skipBtn) skipBtn.classList.add('hidden');
        // QUESTION_ACTIVE → Pause is the relevant CTA, Resume hidden.
        if (pauseBtn) pauseBtn.classList.remove('hidden');
        if (resumeBtn) resumeBtn.classList.add('hidden');

        // Hide reaction bar during game
        var reactionBar = document.getElementById('reaction-bar');
        if (reactionBar) reactionBar.classList.add('hidden');
    }

    // ============================================
    // Round Summary
    // ============================================

    function handleRoundSummary(msg) {
        state.currentPhase = 'ANSWER_REVEAL';
        game.stopCountdown();
        _clearFinaleCountdown();
        pu.showView('reveal-view');

        // Pass question context to reveal
        if (currentQuestion) {
            msg.question_text = currentQuestion.question_text;
            msg.question = { text: currentQuestion.question_text };
        }

        // Enrich all_answers with last answer result (speed/streak breakdown) for current player
        var lastResult = game.getLastAnswerResult ? game.getLastAnswerResult() : null;
        if (lastResult && msg.all_answers) {
            msg.all_answers = msg.all_answers.map(function(a) {
                if (a.player_name === state.playerName) {
                    return Object.assign({}, a, {
                        speed_bonus: lastResult.speed_bonus || 0,
                        streak_bonus: lastResult.streak_bonus || 0,
                        difficulty_multiplier: lastResult.difficulty_multiplier || 1.0,
                        round_score: lastResult.points_earned || 0,
                        streak: lastResult.new_streak || 0,
                    });
                }
                return a;
            });
        }

        reveal.updateRevealView(msg);

        game.clearLastAnswerResult();
        myPowerUp = null;

        // Show reaction bar during reveal
        var reactionBar = document.getElementById('reaction-bar');
        if (reactionBar) reactionBar.classList.remove('hidden');

        // Hide the global admin-control-bar (Pause + Ende) on ANSWER_REVEAL.
        // The redesigned result page owns its own sticky bar with Ende +
        // Nächste Runde — Pause makes no sense between rounds, and having
        // two stacked sticky bars covered the standings.
        var adminBar = document.getElementById('admin-control-bar');
        if (adminBar) adminBar.classList.add('hidden');
        var nextRoundAdminBtn2 = document.getElementById('next-round-admin-btn');
        var skipBtn2 = document.getElementById('skip-question-btn');
        if (nextRoundAdminBtn2) nextRoundAdminBtn2.classList.add('hidden');
        if (skipBtn2) skipBtn2.classList.add('hidden');
    }

    // ============================================
    // Finale
    // ============================================

    function handleFinale(msg) {
        state.currentPhase = 'FINALE';
        game.stopCountdown();
        _clearFinaleCountdown();
        pu.showView('end-view');

        end.updateEndView(msg);
        end.setupNewGameButton();

        // Hide bars
        var reactionBar = document.getElementById('reaction-bar');
        if (reactionBar) reactionBar.classList.add('hidden');
        var adminBar = document.getElementById('admin-control-bar');
        if (adminBar) adminBar.classList.add('hidden');
    }

    // ============================================
    // Paused View
    // ============================================

    function updatePausedView(data) {
        var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
        var titleEl = document.getElementById('pause-title');
        var messageEl = document.getElementById('pause-message');
        var isDisconnect = data.pause_reason === 'admin_disconnected';
        var titleKey = isDisconnect ? 'admin.pausedHostDisconnected' : 'admin.pausedTitle';
        var hintKey = isDisconnect ? 'admin.pausedHostHint' : 'admin.pausedHint';
        if (titleEl) titleEl.textContent = t(titleKey);
        if (messageEl) messageEl.textContent = t(hintKey);
    }

    // ============================================
    // Power-ups
    // ============================================

    function handlePowerUpApplied(msg) {
        if (msg.powerup_type === 'joker' && msg.joker_remove_index != null) {
            // Private send to source with the removed-answer index.
            game.applyJoker(msg.joker_remove_index);
        } else if (msg.powerup_type === 'joker' && msg.source_player !== state.playerName) {
            // Public broadcast — surface opponent's joker use to other
            // players (no removed-index since shuffle is per-player).
            var tJk = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
            pu.showToast(tJk('game.opponentUsedJoker', { name: msg.source_player }), 2000);
        } else if (msg.powerup_type === 'steal') {
            var tPwr = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
            var pts = msg.stolen_points || 0;
            if (msg.source_player === state.playerName) {
                pu.showToast(tPwr('game.stoleFromOpponent', { points: pts, name: msg.target_player || tPwr('lobby.you') }), 2500);
            } else if (msg.target_player === state.playerName) {
                pu.showToast(tPwr('game.stoleFromYou', { name: msg.source_player || tPwr('lobby.you'), points: pts }), 2500);
            }
        } else if (msg.powerup_type === 'freeze' && msg.target_player === state.playerName) {
            var tFrz = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
            pu.showToast(tFrz('game.frozen'), 2000);
        }
        // Only the source's local power-up button needs clearing. Previously
        // this was unconditional — for STEAL/FREEZE that meant a third party
        // who happened to hold a power-up would lose their UI state when an
        // unrelated event broadcasted. Now the only player whose myPowerUp
        // gets reset is the one who just used theirs.
        if (msg.source_player === state.playerName) {
            myPowerUp = null;
            var powerupBtn = document.getElementById('powerup-btn');
            if (powerupBtn) {
                powerupBtn.classList.add('used');
            }
        }
    }

    // ============================================
    // Reactions
    // ============================================

    function showFloatingReaction(emoji, playerName) {
        var container = document.getElementById('reaction-container');
        if (!container) return;

        var el = document.createElement('div');
        el.className = 'floating-reaction';
        el.textContent = emoji;
        el.style.left = (20 + Math.random() * 60) + '%';
        container.appendChild(el);

        setTimeout(function () {
            if (el.parentNode) el.parentNode.removeChild(el);
        }, 2000);
    }

    // ============================================
    // Error Handler
    // ============================================

    function handleError(msg) {
        console.warn('[Quizify] Error:', msg.code, msg.message);
        // Translate via i18n so the player's chosen locale wins. Previous
        // inline map was German-only \u2014 English-speaking players saw "Aktion
        // nicht erlaubt" regardless of language setting. Lookup pattern:
        //   t('errors.<CODE>') returns the localized string OR the key
        //   itself if missing. We treat key-as-result as "no translation"
        //   and fall back to server message, then to errors.UNKNOWN.
        var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
        var key = 'errors.' + (msg.code || 'UNKNOWN');
        var translated = t(key);
        var userMsg;
        if (translated && translated !== key) {
            userMsg = translated;
        } else if (msg.message) {
            userMsg = msg.message;
        } else {
            userMsg = t('errors.UNKNOWN');
        }
        pu.showToast(userMsg);

        // If the error happened during join, reset the button so the user can retry
        if (!state.playerName && els.joinBtn) {
            els.joinBtn.disabled = false;
            els.joinBtn.textContent = t('join.joinButton');
            if (els.nameInput) els.nameInput.style.borderColor = '#D65858';
        }
    }

    // ============================================
    // Join Form
    // ============================================

    function setupJoinForm() {
        if (!els.nameInput || !els.joinBtn) return;

        els.nameInput.addEventListener('input', function () {
            var result = pu.validateName(this.value);
            els.joinBtn.disabled = !result.valid;
        });

        els.joinBtn.addEventListener('click', handleJoinClick);

        els.nameInput.addEventListener('keydown', function (e) {
            if (e.key === 'Enter' && !els.joinBtn.disabled) {
                els.joinBtn.click();
            }
        });
    }

    function handleJoinClick() {
        var result = pu.validateName(els.nameInput.value);
        if (!result.valid) return;

        state.playerName = result.name;
        els.joinBtn.disabled = true;
        els.joinBtn.textContent = t('join.joining');

        if (state.ws && state.ws.readyState === WebSocket.OPEN) {
            var joinMsg = { name: result.name };
            // Admin self-join: server trusts `is_admin: true` in the
            // join message (Beatify pattern). No token validation in
            // this path — see player-core.js connect() for rationale.
            var isAdminSelfJoin = new URLSearchParams(location.search).get('admin') === 'true';
            if (isAdminSelfJoin) {
                state.isAdmin = true;
            }
            if (state.isAdmin) joinMsg.is_admin = true;
            send('join', joinMsg);
        }
    }

    // ============================================
    // Retry Connection
    // ============================================

    function setupRetryConnection() {
        var retryBtn = document.getElementById('retry-connection-btn');
        if (retryBtn) {
            retryBtn.addEventListener('click', function () {
                state.reconnectAttempts = 0;
                pu.showView('loading-view');
                connect();
            });
        }
    }

    // ============================================
    // Admin Controls Wiring
    // ============================================

    function setupAdminControls() {
        // Skip question
        var skipBtn = document.getElementById('skip-question-btn');
        if (skipBtn) {
            skipBtn.addEventListener('click', function () {
                send('admin_skip', {});
            });
        }

        // Next round (from admin bar)
        var nextRoundAdminBtn = document.getElementById('next-round-admin-btn');
        if (nextRoundAdminBtn) {
            nextRoundAdminBtn.addEventListener('click', function () {
                send('next_round', {});
            });
        }

        // End game
        var endGameBtn = document.getElementById('end-game-btn');
        if (endGameBtn) {
            endGameBtn.addEventListener('click', function () {
                send('end_game', {});
            });
        }

        // Pause / resume — toggled by handleGameState based on phase.
        var pauseBtn = document.getElementById('pause-game-btn');
        if (pauseBtn) {
            pauseBtn.addEventListener('click', function () { send('pause_game', {}); });
        }
        var resumeBtn = document.getElementById('resume-game-btn');
        if (resumeBtn) {
            resumeBtn.addEventListener('click', function () { send('resume_game', {}); });
        }

        // Next round (from reveal view)
        var nextRoundBtn = document.getElementById('next-round-btn');
        if (nextRoundBtn) {
            nextRoundBtn.addEventListener('click', function () {
                nextRoundBtn.disabled = true;
                send('next_round', {});
            });
        }

        // End game from the reveal page's sticky admin bar. Same server
        // semantics as end-game-btn — added because the redesign moved
        // the admin actions to a bottom-sticky bar on the reveal page.
        var endFromReveal = document.getElementById('end-game-from-reveal-btn');
        if (endFromReveal) {
            endFromReveal.addEventListener('click', function () {
                send('end_game', {});
            });
        }
    }

    // ============================================
    // Reaction Bar Wiring
    // ============================================

    function setupReactionBar() {
        var reactionBtns = document.querySelectorAll('.reaction-btn');
        reactionBtns.forEach(function (btn) {
            btn.addEventListener('click', function () {
                var emoji = btn.dataset.emoji;
                if (emoji) {
                    send('reaction', { emoji: emoji });
                    btn.classList.add('reaction-btn--sent');
                    setTimeout(function () {
                        btn.classList.remove('reaction-btn--sent');
                    }, 500);
                }
            });
        });
    }

    // ============================================
    // Initialization
    // ============================================

    // ============================================
    // Sound Toggle (header speaker button)
    // ============================================

    function setupSoundToggle() {
        var btn = document.getElementById('sound-toggle-btn');
        var snd = window.QuizifyPlayerSound;
        if (!btn) return;
        if (!snd) { btn.classList.add('hidden'); return; }

        function render() {
            var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
            var muted = snd.isMuted();
            btn.textContent = muted ? '🔇' : '🔊';
            btn.classList.toggle('is-muted', muted);
            btn.setAttribute('aria-pressed', muted ? 'true' : 'false');
            var label = muted ? t('game.soundUnmute') : t('game.soundMute');
            btn.setAttribute('aria-label', label);
            btn.setAttribute('title', label);
        }

        btn.addEventListener('click', function () {
            snd.toggleMute();
            render();
        });
        render();
    }

    function init() {
        pu.paintUiIcons();
        setupJoinForm();
        lobby.init(send);
        setupRetryConnection();
        setupAdminControls();
        setupReactionBar();
        setupSoundToggle();
        pu.setupCollapsibles();
        if (lightning) { lightning.setSend(send); lightning.init(); }

        // Answer button clicks
        var answerButtons = document.getElementById('answer-buttons');
        if (answerButtons) {
            answerButtons.addEventListener('click', function (e) {
                var btn = e.target.closest('.answer-btn');
                if (!btn || btn.disabled) return;
                var index = parseInt(btn.dataset.index, 10);
                if (!isNaN(index)) {
                    game.handleAnswerClick(index, send);
                }
            });
        }

        // Power-up button — freeze/steal open a target picker; the rest fire
        // immediately. Server still falls back to a random opponent if
        // target_player_id is null, so even older clients keep working.
        var powerupBtn = document.getElementById('powerup-btn');
        if (powerupBtn) {
            powerupBtn.addEventListener('click', function () {
                if (!myPowerUp) return;
                if (game && game.powerupNeedsTarget && game.powerupNeedsTarget(myPowerUp)) {
                    game.openTargetPicker(myPowerUp, function (targetName) {
                        send('use_powerup', { target_player_id: targetName });
                    });
                } else {
                    send('use_powerup', { target_player_id: null });
                }
            });
        }

        // Auto-fill name from URL param ?name=... (admin self-join)
        var urlParams = new URLSearchParams(location.search);
        var prefilledName = urlParams.get('name');
        if (prefilledName && els.nameInput) {
            els.nameInput.value = prefilledName;
            els.joinBtn.disabled = false;
            // Set state.playerName so the auto-join path fires on WS open
            // (otherwise the user has to click the button manually).
            state.playerName = prefilledName;
        }

        // Check if admin via URL param
        if (urlParams.get('admin') === 'true') {
            state.isAdmin = true;
        }

        // i18n init
        if (window.QuizifyI18n) {
            QuizifyI18n.init().then(function () {
                QuizifyI18n.initPageTranslations();
                // game_state may have already arrived before i18n loaded;
                // re-fire the title update so we don't sit on the stale
                // "— Beitreten" forever (see updatePageTitle for the why).
                _flushPendingTitle();
            });
        }

        // Always show join-view immediately — don't wait for WS.
        // For pre-filled names (admin self-join), the form is visible but
        // auto-submit fires once WS opens. Prevents a blank screen on slow
        // connections such as Nabu Casa remote access.
        pu.showView('join-view');
        if (els.joinBtn) els.joinBtn.disabled = true;

        // Connect WebSocket
        pu.updateConnectionIndicator('reconnecting');
        connect();

        // Fallback: if WS hasn't opened after 10s, re-enable join button with error hint
        _wsOpenTimeout = setTimeout(function () {
            if (!state.ws || state.ws.readyState !== WebSocket.OPEN) {
                if (els.joinBtn) {
                    var tRetry = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
                    els.joinBtn.disabled = false;
                    els.joinBtn.textContent = tRetry('connection.retryConnection');
                    els.joinBtn.addEventListener('click', function retryOnce() {
                        els.joinBtn.removeEventListener('click', retryOnce);
                        els.joinBtn.disabled = true;
                        els.joinBtn.textContent = tRetry('join.joinButton');
                        state.reconnectAttempts = 0;
                        connect();
                    }, { once: true });
                }
                pu.updateConnectionIndicator('disconnected');
            }
        }, 10000);

        // Auto-join if name was pre-filled
        if (prefilledName) {
            var autoJoinInterval = setInterval(function () {
                if (state.ws && state.ws.readyState === WebSocket.OPEN) {
                    clearInterval(autoJoinInterval);
                    els.joinBtn.click();
                }
            }, 200);
            setTimeout(function () { clearInterval(autoJoinInterval); }, 5000);
        }

        // iOS Safari reconnect on foreground
        document.addEventListener('visibilitychange', function () {
            if (document.visibilityState === 'visible') {
                var ws = state.ws;
                if (!ws || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
                    if (state.playerName) {
                        console.log('[Quizify] Page visible, WS dead \u2014 reconnecting.');
                        state.reconnectAttempts = 0;
                        connect();
                    }
                }
                // The OS releases wake locks when the tab hides \u2014 re-acquire
                // when the player tabs back in mid-question.
                if (state.currentPhase === 'QUESTION_ACTIVE' || state.currentPhase === 'PLAYING') {
                    _acquireWakeLock();
                }
            }
        });

        // Refresh / retry buttons
        var refreshBtn = document.getElementById('refresh-btn');
        if (refreshBtn) {
            refreshBtn.addEventListener('click', function () {
                pu.showView('loading-view');
                connect();
            });
        }
        var retryBtn = document.getElementById('retry-btn');
        if (retryBtn) {
            retryBtn.addEventListener('click', function () {
                pu.showView('loading-view');
                connect();
            });
        }

        // Safety watchdog against a blank screen. A dead-reconnect URL
        // (?name=X&admin=true&reconnect=1 with no live session) sends a
        // `join` that yields no game_state, so neither the reconnect_failed
        // handler (#227) nor the game_state default (#228) fires — the player
        // was left on no/loading view. A few seconds after boot, if no real
        // view has rendered (still on loading or nothing) and no game state
        // ever arrived, fall back to the join screen so there's always a way
        // forward instead of a blank page.
        setTimeout(function () {
            var visible = [].slice.call(document.querySelectorAll('.view'))
                .find(function (e) { return e.offsetParent !== null; });
            var stuck = !visible || visible.id === 'loading-view';
            if (stuck && state.currentPhase == null) {
                pu.showView('join-view');
            }
        }, 4000);
    }

    // ============================================
    // Boot
    // ============================================

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }

    // ============================================
    // Export
    // ============================================

    window.QuizifyPlayer = {
        init: init,
        send: send
    };

    // #215: hook for sw-update.js — is the player screen idle enough that a
    // service-worker-triggered reload won't interrupt anything? Idle = join,
    // lobby, the per-round reveal, the lightning recap, and the finale end
    // screen. NOT idle during a live question, a live lightning round, or a
    // paused game (resuming reloads straight back into a question).
    window.quizifyIsIdleForReload = function () {
        switch (state.currentPhase) {
            case 'QUESTION_ACTIVE':
            case 'PLAYING':
            case 'LIGHTNING':
            case 'PAUSED':
                return false;
            default:
                // LOBBY, ANSWER_REVEAL/REVEAL, LIGHTNING_RECAP, FINALE/END,
                // and the pre-join state.
                return true;
        }
    };

})();
